actions.script:
const asList = (value) => (value == null ? [] : (typeof value === 'string' ? value.split(',') : Array.from(value)))
        .map((id) => String(id).trim()).filter((id) => id)
recipientList = []
const toIds = []
const ccIds = []
for (const id of (toPartyId ? [toPartyId] : []).concat(asList(toPartyIdList))) if (!toIds.includes(id)) toIds.push(id)
for (const id of asList(ccPartyIdList).concat(asList(mentionPartyIdList))) {
    if (!toIds.includes(id) && !ccIds.includes(id)) ccIds.push(id)
}
const named = toIds.concat(ccIds)
if (named.length) {
    const found = new Set(Array.from(ec.entity.find('mantle.party.Party').condition('partyId', 'in', named)
            .selectField('partyId').disableAuthz().list()).map((party) => party.partyId))
    const missing = named.filter((id) => !found.has(id))
    if (missing.length) { ec.message.addError(`Party ${missing.join(', ')} not found`); return }
}
toPartyId = toIds.length ? toIds[0] : null

const findEvent = (id) => ec.entity.find('mantle.party.communication.CommunicationEvent').condition('communicationEventId', id).one()
if (parentCommEventId) {
    const parent = findEvent(parentCommEventId)
    if (parent == null) { ec.message.addError(`Communication event ${parentCommEventId} not found`); return }
    if (!rootCommEventId) rootCommEventId = parent.rootCommEventId || parent.communicationEventId
}

// the recipients by priority: to, cc, then the mailbox's members and the thread's participants
const roles = new Map()
for (const id of toIds) roles.set(id, 'MessageTo')
for (const id of ccIds) if (!roles.has(id)) roles.set(id, 'MessageCc')
if (contactListId) {
    const access = ec.service.sync().name('mantle.marketing.ContactListServices.get#ContactListAccess')
            .parameters({contactListId: contactListId, partyId: fromPartyId}).call()
    if (!access.exists || !access.canSeeHeader) { ec.message.addError(`Contact list ${contactListId} not found`); return }
    if (access.isMailbox) {
        const listName = access.contactList?.contactListName || contactListId
        if (!access.canPost) {
            ec.message.addError(access.isArchived ? `Mailbox ${listName} is archived` : `You may not post to mailbox ${listName}`)
            return
        }
        let threadEvents = []
        if (rootCommEventId) {
            const root = findEvent(rootCommEventId)
            if (root == null) { ec.message.addError(`Communication event ${rootCommEventId} not found`); return }
            if (root.contactListId !== contactListId) {
                ec.message.addError(`Communication event ${rootCommEventId} is not a post in mailbox ${listName}`); return }
            if (root.statusId === 'CeResolved') { ec.message.addError(`This thread in mailbox ${listName} is closed`); return }
            const cf = ec.entity.conditionFactory
            threadEvents = Array.from(ec.entity.find('mantle.party.communication.CommunicationEvent')
                    .condition(cf.makeCondition([cf.makeCondition('communicationEventId', 'equals', rootCommEventId),
                        cf.makeCondition('rootCommEventId', 'equals', rootCommEventId)], 'or'))
                    .condition(cf.makeCondition('statusId', 'not-equals', 'CeCancelled', true))
                    .selectField('communicationEventId').selectField('fromPartyId').selectField('toPartyId').list())
            const threadIds = threadEvents.map((event) => event.communicationEventId)
            const threadRows = threadIds.length ? Array.from(ec.entity.find('mantle.party.communication.CommunicationEventParty')
                    .condition('communicationEventId', 'in', threadIds).list()) : []
            // a poster who may not read every thread (a help mailbox's non-member) posts only in their own
            if (!access.canReadAll && !threadEvents.some((event) => event.fromPartyId === fromPartyId || event.toPartyId === fromPartyId)
                    && !threadRows.some((row) => row.partyId === fromPartyId)) {
                ec.message.addError(`Communication event ${rootCommEventId} not found`); return }
            if (access.isPublic || access.postingEnumId === 'ClpAnyUser') {
                const participants = []
                for (const event of threadEvents) for (const id of [event.fromPartyId, event.toPartyId]) if (id) participants.push(id)
                for (const row of threadRows) if (row.roleTypeId === 'MessageTo' || row.roleTypeId === 'MessageCc') participants.push(row.partyId)
                for (const id of participants) if (id !== fromPartyId && !roles.has(id)) roles.set(id, 'MessageMailbox')
            }
        }
        for (const row of ec.entity.find('mantle.marketing.contact.ContactListParty').condition('contactListId', contactListId)
                .condition('statusId', 'CLPT_ACCEPTED').condition(ec.entity.conditionFactory.makeConditionDate('fromDate', 'thruDate', null))
                .orderBy('fromDate').list()) {
            if (row.partyId !== fromPartyId && !roles.has(row.partyId)) roles.set(row.partyId, 'MessageMailbox')
        }
    }
}
recipientList = Array.from(roles.entries()).map(([partyId, roleTypeId]) => ({partyId: partyId, roleTypeId: roleTypeId}))

newMailUserIds = []
for (const recipient of recipientList) {
    ec.service.sync().name('create#mantle.party.communication.CommunicationEventParty').parameters({
        communicationEventId: communicationEventId, partyId: recipient.partyId, roleTypeId: recipient.roleTypeId,
        statusId: 'CepReceived'}).call()
    if (ec.message.hasError()) return
}
// the alert of new mail in the Inbox; notify#NewMail logs its own failures
if (communicationEventTypeId === 'Message' && recipientList.length) {
    const alert = ec.service.sync().name('mantle.party.CommunicationServices.notify#NewMail')
            .parameter('communicationEventId', communicationEventId).call()
    newMailUserIds = alert?.notifiedUserIds ?? []
}

const asList = (value) => (value == null ? [] : (typeof value === 'string' ? value.split(',') : Array.from(value)))
        .map((id) => String(id).trim()).filter((id) => id)
const parent = ec.entity.find('mantle.party.communication.CommunicationEvent').condition('communicationEventId', parentCommEventId).one()
if (parent == null) { ec.message.addError(`Communication event ${parentCommEventId} not found`); return }
const isMessage = parent.communicationEventTypeId === 'Message'
communicationEventTypeId = isMessage ? 'Message' : 'Comment'
rootCommEventId = parent.rootCommEventId || parentCommEventId
contactListId = null
const rowsOf = (roleTypeId) => Array.from(ec.entity.find('mantle.party.communication.CommunicationEventParty')
        .condition('communicationEventId', parentCommEventId).condition('roleTypeId', roleTypeId).list()).map((row) => row.partyId)

if (isMessage) {
    // the replier sees the parent: from, to or a recipient of it, or a post of a mailbox it may read
    let visible = parent.fromPartyId === fromPartyId || parent.toPartyId === fromPartyId ||
            ec.entity.find('mantle.party.communication.CommunicationEventParty').condition('communicationEventId', parentCommEventId)
                .condition('partyId', fromPartyId).count() > 0
    if (!visible && parent.contactListId) {
        const access = ec.service.sync().name('mantle.marketing.ContactListServices.get#ContactListAccess')
                .parameters({contactListId: parent.contactListId, partyId: fromPartyId}).call()
        // a help mailbox's non-member only in their own thread, which create#Message checks
        visible = access.isMailbox && (access.canReadAll || access.canReadOwn)
    }
    if (!visible) { ec.message.addError(`Communication event ${parentCommEventId} not found`); return }
}

const toIds = []
const ccIds = []
const addTo = (id) => { if (id && !toIds.includes(id)) toIds.push(id) }
if (!isMessage || replyToSenderOnly) {
    addTo(parent.fromPartyId === fromPartyId ? parent.toPartyId : parent.fromPartyId)
} else if (parent.contactListId) {
    contactListId = parent.contactListId
} else {
    for (const id of [parent.fromPartyId, parent.toPartyId].concat(rowsOf('MessageTo'))) if (id !== fromPartyId) addTo(id)
    for (const id of rowsOf('MessageCc')) if (id !== fromPartyId && !toIds.includes(id) && !ccIds.includes(id)) ccIds.push(id)
}
for (const id of asList(toPartyIdList)) addTo(id)

const out = ec.service.sync().name('mantle.party.CommunicationServices.create#Message').parameters({
    communicationEventTypeId: communicationEventTypeId, contactMechTypeEnumId: 'CmtWebForm', statusId: statusId,
    parentCommEventId: parentCommEventId, rootCommEventId: rootCommEventId, fromPartyId: fromPartyId,
    toPartyIdList: toIds, ccPartyIdList: ccIds.concat(asList(ccPartyIdList)), mentionPartyIdList: mentionPartyIdList,
    contactListId: contactListId, entryDate: ec.user.nowTimestamp, contentType: contentType, subject: subject, body: body}).call()
if (ec.message.hasError()) return
communicationEventId = out.communicationEventId
toPartyId = out.toPartyId ?? null

const cf = ec.entity.conditionFactory
threadMap = {}
const partyId = ec.user.userAccount?.partyId || null
const rootIds = Array.from(new Set(Array.from(rootCommEventIdList || []).map((id) => String(id))))
if (!partyId || rootIds.length === 0) return
const rootSet = new Set(rootIds)
const events = Array.from(ec.entity.find('mantle.party.communication.CommunicationEvent')
        .condition(cf.makeCondition([cf.makeCondition('communicationEventId', 'in', rootIds),
            cf.makeCondition('rootCommEventId', 'in', rootIds)], 'or'))
        .condition(cf.makeCondition('statusId', 'not-equals', 'CeCancelled', true))
        .orderBy('entryDate').orderBy('communicationEventId').list()).map((value) => value.getMap())
if (events.length === 0) return
const eventIds = events.map((event) => event.communicationEventId)

const myRows = new Map()
const recipients = new Map()
for (const value of ec.entity.find('mantle.party.communication.CommunicationEventParty').condition('communicationEventId', 'in', eventIds)
        .condition(cf.makeCondition([cf.makeCondition('partyId', 'equals', partyId),
            cf.makeCondition('roleTypeId', 'in', ['MessageTo', 'MessageCc'])], 'or')).orderBy('partyId').list()) {
    const row = value.getMap()
    if (row.partyId === partyId) {
        if (!myRows.has(row.communicationEventId)) myRows.set(row.communicationEventId, [])
        myRows.get(row.communicationEventId).push({roleTypeId: row.roleTypeId, readDate: row.readDate ?? null,
            isFlagged: row.isFlagged ?? null, archivedDate: row.archivedDate ?? null, snoozedThruDate: row.snoozedThruDate ?? null,
            statusId: row.statusId ?? null})
    }
    if (row.roleTypeId === 'MessageTo' || row.roleTypeId === 'MessageCc') {
        if (!recipients.has(row.communicationEventId)) recipients.set(row.communicationEventId, {to: [], cc: []})
        recipients.get(row.communicationEventId)[row.roleTypeId === 'MessageTo' ? 'to' : 'cc'].push(row.partyId)
    }
}
const attachments = new Map()
for (const value of ec.entity.find('mantle.party.communication.CommunicationEventContent').condition('communicationEventId', 'in', eventIds)
        .orderBy('sequenceNum').orderBy('contentDate').list()) {
    if (!attachments.has(value.communicationEventId)) attachments.set(value.communicationEventId, [])
    attachments.get(value.communicationEventId).push({communicationEventContentId: value.communicationEventContentId,
        contentLocation: value.contentLocation ?? null, description: value.description ?? null,
        contentTypeEnumId: value.contentTypeEnumId ?? null, contentDate: value.contentDate ?? null})
}
const accessByList = new Map()
const accessOf = (contactListId) => {
    if (!accessByList.has(contactListId)) accessByList.set(contactListId, ec.service.sync()
            .name('mantle.marketing.ContactListServices.get#ContactListAccess').parameter('contactListId', contactListId).call())
    return accessByList.get(contactListId)
}

const byThread = new Map()
for (const event of events) {
    const threadId = rootSet.has(event.communicationEventId) ? event.communicationEventId : event.rootCommEventId
    if (!byThread.has(threadId)) byThread.set(threadId, [])
    byThread.get(threadId).push(event)
}
for (const [threadId, messages] of byThread) {
    const mine = (event) => event.fromPartyId === partyId || event.toPartyId === partyId || myRows.has(event.communicationEventId)
    const takesPart = messages.some(mine)
    const visible = messages.filter((event) => {
        if (mine(event)) return true
        if (!event.contactListId) return false
        const access = accessOf(event.contactListId)
        return access.isMailbox && (access.canReadAll || (access.canReadOwn && takesPart))
    })
    if (visible.length === 0) continue
    const root = messages.find((event) => event.communicationEventId === threadId) || null
    const listId = root?.contactListId || null
    const access = listId ? accessOf(listId) : null
    const isMailbox = !!access?.isMailbox
    threadMap[threadId] = {rootCommEventId: threadId, root: root, subject: root?.subject ?? visible[0].subject ?? null,
        contactListId: listId, contactListName: access?.contactList?.contactListName ?? null, isMailbox: isMailbox,
        isClosed: isMailbox && root?.statusId === 'CeResolved', takesPart: takesPart,
        canReadAll: isMailbox ? access.canReadAll : null, canPost: isMailbox ? access.canPost : null,
        canModerate: isMailbox ? access.canModerate : false,
        messageList: visible.map((event) => Object.assign({}, event, {myRowList: myRows.get(event.communicationEventId) || [],
            toPartyIdList: recipients.get(event.communicationEventId)?.to ?? [],
            ccPartyIdList: recipients.get(event.communicationEventId)?.cc ?? [],
            attachmentList: attachments.get(event.communicationEventId) || []}))}
}

const cf = ec.entity.conditionFactory
const DELIVERY = ['MessageTo', 'MessageCc', 'MessageMailbox']
let TYPES = ['Message', 'Comment']
const toMillis = (value) => {
    if (value == null || value === '') return null
    if (typeof value === 'number') return value
    if (value instanceof Date) return value.getTime()
    const number = Number(value)
    return Number.isNaN(number) ? new Date(String(value)).getTime() : number
}
threadList = []
hasMore = false
nextBeforeDate = null
const partyId = ec.user.userAccount?.partyId || null
if (!partyId) { ec.message.addError('Internal messages need a user with a party'); return }
if (!(pageSize > 0)) pageSize = 50
// the user's labels on messages, once: a missing EmailLabel (deleted) is left out
const labelByEvent = new Map()
const labelJoins = Array.from(ec.entity.find('mantle.party.communication.CommunicationEventPartyLabel').condition('partyId', partyId).list())
if (labelJoins.length) {
    const known = {}
    const labelIds = Array.from(new Set(labelJoins.map((row) => row.emailLabelId)))
    for (const label of ec.entity.find('moqui.basic.email.EmailLabel').condition('emailLabelId', 'in', labelIds).list())
        known[label.emailLabelId] = {emailLabelId: label.emailLabelId, labelName: label.labelName ?? null, color: label.color ?? null}
    for (const row of labelJoins) {
        const label = known[row.emailLabelId]
        if (!label) continue
        const list = labelByEvent.get(row.communicationEventId) || []
        list.push(label)
        labelByEvent.set(row.communicationEventId, list)
    }
}
const labelsOf = (messages) => {
    const byId = new Map()
    for (const message of messages) for (const label of (labelByEvent.get(message.communicationEventId) || [])) byId.set(label.emailLabelId, label)
    return Array.from(byId.values())
}
const now = ec.user.nowTimestamp
const nowMillis = toMillis(now)

// the search line: its terms once (find#InboxThreads passes them parsed), as conditions on the messages that put a
// thread in the view and as filters of the thread
let terms = searchTermMap || null
if (terms == null && searchText && String(searchText).trim()) {
    terms = ec.service.sync().name('org.moqui.impl.EmailClientServices.parse#SearchText').parameter('searchText', searchText).call()
    if (ec.message.hasError()) return
}
const messageConditions = []
const threadFilters = []
let matchesNothing = false
if (terms) {
    const like = (field, text) => cf.makeCondition(field, 'like', `%${text}%`, false, true)
    const notLike = (field, text) => cf.makeCondition(field, 'not-like', `%${text}%`, true, true)
    const idsIn = (field, ids) => ids.length ? cf.makeCondition(field, 'in', ids) : null
    // the parties whose name (every part of the text in a first, last or organization name), user name or email
    // address has the text; only ids, to match the messages the user sees
    const partyCache = {}
    const partiesMatching = (text) => {
        const key = String(text).toLowerCase().trim()
        if (partyCache[key]) return partyCache[key]
        const found = new Set()
        const parts = key.split(/\s+/).filter((part) => part)
        if (parts.length) {
            const nameCondition = cf.makeCondition(parts.map((part) => cf.makeCondition([like('firstName', part), like('lastName', part),
                like('organizationName', part)], 'or')), 'and')
            for (const row of ec.entity.find('mantle.party.PartyDetail').condition(nameCondition).selectField('partyId').limit(500)
                    .disableAuthz().list()) found.add(row.partyId)
        }
        for (const row of ec.entity.find('moqui.security.UserAccount').condition(cf.makeCondition([like('username', key),
                like('emailAddress', key), like('userFullName', key)], 'or')).condition('partyId', 'not-equals', null)
                .selectField('partyId').limit(500).disableAuthz().list()) found.add(row.partyId)
        const mechIds = Array.from(ec.entity.find('mantle.party.contact.ContactMech').condition('contactMechTypeEnumId', 'CmtEmailAddress')
                .condition(like('infoString', key)).selectField('contactMechId').limit(500).disableAuthz().list()).map((row) => row.contactMechId)
        if (mechIds.length) for (const row of ec.entity.find('mantle.party.contact.PartyContactMech').condition('contactMechId', 'in', mechIds)
                .selectField('partyId').disableAuthz().list()) found.add(row.partyId)
        partyCache[key] = Array.from(found)
        return partyCache[key]
    }
    // the messages with a recipient row of those parties in those roles
    const eventsWithRows = (ids, roles) => ids.length ? Array.from(new Set(Array.from(ec.entity.find('mantle.party.communication.CommunicationEventParty')
            .condition('partyId', 'in', ids).condition('roleTypeId', 'in', roles).selectField('communicationEventId').limit(5000).list())
            .map((row) => row.communicationEventId))) : []
    const DAY = 86400000
    const dayOf = (text) => {
        let match = /^(\d{4})[\/.-](\d{1,2})[\/.-](\d{1,2})$/.exec(text)
        let parts = match ? [match[1], match[2], match[3]] : null
        if (!parts && (match = /^(\d{1,2})\/(\d{1,2})\/(\d{4})$/.exec(text))) parts = [match[3], match[1], match[2]]
        if (!parts) return null
        const pad = (value) => String(value).padStart(2, '0')
        return ec.l10n.parseTimestamp(`${parts[0]}-${pad(parts[1])}-${pad(parts[2])} 00:00:00`, 'yyyy-MM-dd HH:mm:ss')
    }
    const agoOf = (text) => {
        const match = /^(\d+)\s*([dwmy])$/i.exec(text)
        if (!match) return null
        return new Date(nowMillis - Number(match[1]) * {d: DAY, w: 7 * DAY, m: 30 * DAY, y: 365 * DAY}[match[2].toLowerCase()])
    }
    const IN_VIEWS = {inbox: 'received', sent: 'sent', flagged: 'flagged', starred: 'flagged', snoozed: 'snoozed', archive: 'archived',
        archived: 'archived', all: 'all', allmail: 'all', 'all mail': 'all', anywhere: 'all'}
    for (const term of Array.from(terms.termList || [])) {
        const value = String(term.value)
        const negate = term.negate === true
        switch (term.operator) {
            case 'in':
                if (IN_VIEWS[value]) view = IN_VIEWS[value]
                else matchesNothing = true
                break
            case 'from': {
                const ids = partiesMatching(value)
                if (negate) { if (ids.length) messageConditions.push(cf.makeCondition('fromPartyId', 'not-in', ids, true)) }
                else if (ids.length) messageConditions.push(cf.makeCondition('fromPartyId', 'in', ids))
                else matchesNothing = true
                break
            }
            case 'to': case 'cc': {
                const ids = partiesMatching(value)
                const rowIds = eventsWithRows(ids, term.operator === 'cc' ? ['MessageCc'] : ['MessageTo', 'MessageCc'])
                const toCondition = term.operator === 'cc' ? null : idsIn('toPartyId', ids)
                const either = [toCondition, idsIn('communicationEventId', rowIds)].filter((condition) => condition)
                if (negate) {
                    if (ids.length && term.operator !== 'cc') messageConditions.push(cf.makeCondition('toPartyId', 'not-in', ids, true))
                    if (rowIds.length) messageConditions.push(cf.makeCondition('communicationEventId', 'not-in', rowIds))
                } else if (either.length) messageConditions.push(cf.makeCondition(either, 'or'))
                else matchesNothing = true
                break
            }
            case 'subject': messageConditions.push(negate ? notLike('subject', value) : like('subject', value)); break
            case 'before': case 'after': {
                const day = dayOf(value)
                if (day == null) { ec.message.addError(`${term.operator}:${value} needs a date, such as ${term.operator}:2026/10/19`); return }
                const before = (term.operator === 'before') !== negate
                messageConditions.push(cf.makeCondition('entryDate', before ? 'less' : 'greater-equals', day))
                break
            }
            case 'older_than': case 'newer_than': {
                const at = agoOf(value)
                if (at == null) { ec.message.addError(`${term.operator}:${value} needs a count of days, weeks, months or years, such as ${term.operator}:2d`); return }
                const older = (term.operator === 'older_than') !== negate
                messageConditions.push(cf.makeCondition('entryDate', older ? 'less' : 'greater-equals', at))
                break
            }
            case 'has': threadFilters.push((summary) => summary.hasAttachment !== negate); break
            case 'filename': {
                const needle = value.toLowerCase()
                const named = (thread) => thread.messageList.some((message) => message.attachmentList.some((item) =>
                        String(item.description || item.contentLocation || '').toLowerCase().includes(needle)))
                threadFilters.push((summary, thread) => named(thread) !== negate)
                break
            }
            case 'is':
                if (value === 'unread') threadFilters.push((summary) => summary.isUnread !== negate)
                else if (value === 'read') threadFilters.push((summary) => summary.isUnread === negate)
                else if (value === 'flagged' || value === 'starred') threadFilters.push((summary) => summary.isFlagged !== negate)
                else if (value === 'snoozed') threadFilters.push((summary) => (summary.snoozedThruDate != null) !== negate)
                else if (!negate) matchesNothing = true
                break
            case 'label': {
                const needle = value.toLowerCase()
                const matching = new Set()
                for (const [eventId, list] of labelByEvent) if (list.some((label) => String(label.labelName || '').toLowerCase().includes(needle))) matching.add(eventId)
                threadFilters.push((summary, thread) => thread.messageList.some((message) => matching.has(message.communicationEventId)) !== negate)
                if (!negate && matching.size === 0) matchesNothing = true
                break
            }
            // what internal messages do not have: none match, and all with a -
            case 'bcc': case 'larger': case 'smaller':
                if (!negate) matchesNothing = true
                break
            default: ec.message.addError(`${term.operator}: is not a search term`); return
        }
    }
    // the free text: each word in the subject, the body or the sender's name; each phrase in the subject or body;
    // no -word in either
    for (const word of Array.from(terms.wordList || [])) {
        const ids = partiesMatching(word)
        messageConditions.push(cf.makeCondition([like('subject', word), like('body', word)].concat(ids.length ? [cf.makeCondition('fromPartyId', 'in', ids)] : []), 'or'))
    }
    for (const phrase of Array.from(terms.phraseList || [])) messageConditions.push(cf.makeCondition([like('subject', phrase), like('body', phrase)], 'or'))
    for (const text of Array.from(terms.excludeList || [])) messageConditions.push(cf.makeCondition([notLike('subject', text), notLike('body', text)], 'and'))
}
if (!view) view = contactListId ? 'all' : 'received'
if (!['received', 'sent', 'flagged', 'snoozed', 'archived', 'comments', 'all'].includes(view)) {
    ec.message.addError(`Unknown view ${view}: received, sent, flagged, snoozed, archived, comments or all`); return }
if (emailLabelId) {
    const accountId = ec.service.sync().name('org.moqui.impl.EmailClientServices.ensure#InternalAccount').call()?.emailAccountId
    const label = ec.entity.find('moqui.basic.email.EmailLabel').condition('emailLabelId', emailLabelId).one()
    if (ec.message.hasError()) return
    if (label == null || label.emailAccountId !== accountId) { ec.message.addError(`Email label ${emailLabelId} not found`); return }
    threadFilters.push((summary, thread) => thread.messageList.some((message) => (labelByEvent.get(message.communicationEventId) || [])
            .some((item) => item.emailLabelId === emailLabelId)))
}
if (view === 'comments') TYPES = ['Comment']
if (needsReply) threadFilters.push((summary, thread) => {
    const last = thread.messageList[thread.messageList.length - 1]
    return !summary.isArchived && last.fromPartyId !== partyId && toMillis(last.entryDate) <= nowMillis - 86400000 &&
            last.myRowList.some((row) => row.roleTypeId === 'MessageTo' || row.roleTypeId === 'MessageCc')
})
if (matchesNothing) return

if (contactListId) {
    const access = ec.service.sync().name('mantle.marketing.ContactListServices.get#ContactListAccess')
            .parameter('contactListId', contactListId).call()
    if (!access.exists || !access.isMailbox || !access.canSeeHeader) { ec.message.addError(`Mailbox ${contactListId} not found`); return }
    // a join request sees only the header
    if (!access.canReadOwn) return
}
// the Inbox leaves out the posts of the mailboxes the user takes as Mailbox only
let mailboxOnlyIds = []
if (view === 'received' && !contactListId) {
    const memberRows = Array.from(ec.entity.find('mantle.marketing.contact.ContactListParty').condition('partyId', partyId)
            .condition('statusId', 'CLPT_ACCEPTED').condition(cf.makeConditionDate('fromDate', 'thruDate', null)).list())
    const listIds = Array.from(new Set(memberRows.map((row) => row.contactListId)))
    const defaults = {}
    if (listIds.length) for (const list of ec.entity.find('mantle.marketing.contact.ContactList').condition('contactListId', 'in', listIds)
            .selectField('contactListId').selectField('defaultDeliveryEnumId').list()) defaults[list.contactListId] = list.defaultDeliveryEnumId
    mailboxOnlyIds = Array.from(new Set(memberRows.filter((row) => (row.deliveryEnumId || defaults[row.contactListId] || 'CldInbox') === 'CldMailboxOnly')
            .map((row) => row.contactListId)))
}

const notCancelled = cf.makeCondition('statusId', 'not-equals', 'CeCancelled', true)
// the messages that put a thread in the view
const byEvents = view === 'sent' || (contactListId && view === 'all')
const makeFind = () => {
    let find
    if (byEvents) {
        find = ec.entity.find('mantle.party.communication.CommunicationEvent')
        if (view === 'sent') find = find.condition('fromPartyId', partyId).condition(cf.makeCondition([
            cf.makeCondition('communicationEventTypeId', 'equals', 'Message'), cf.makeCondition('toPartyId', 'not-equals', null),
            cf.makeCondition('contactListId', 'not-equals', null)], 'or'))
    } else {
        find = ec.entity.find('mantle.party.communication.CommunicationEventPartyAndEvent').condition('partyId', partyId)
                .condition('roleTypeId', 'in', DELIVERY)
        const notSnoozed = cf.makeCondition([cf.makeCondition('snoozedThruDate', 'equals', null),
            cf.makeCondition('snoozedThruDate', 'less-equals', now)], 'or')
        if (view === 'received') {
            find = find.condition('archivedDate', null).condition(notSnoozed)
            if (mailboxOnlyIds.length) find = find.condition(cf.makeCondition([cf.makeCondition('roleTypeId', 'in', ['MessageTo', 'MessageCc']),
                cf.makeCondition('contactListId', 'not-in', mailboxOnlyIds)], 'or'))
        } else if (view === 'flagged') find = find.condition('isFlagged', 'Y')
        else if (view === 'snoozed') find = find.condition('archivedDate', null).condition(cf.makeCondition('snoozedThruDate', 'greater', now))
        else if (view === 'archived') find = find.condition(cf.makeCondition('archivedDate', 'not-equals', null))
        if (unreadOnly) find = find.condition('readDate', null)
    }
    find = find.condition('communicationEventTypeId', 'in', TYPES).condition(notCancelled)
    if (contactListId) find = find.condition('contactListId', contactListId)
    for (const condition of messageConditions) find = find.condition(condition)
    return find.selectField('communicationEventId').selectField('rootCommEventId').selectField('entryDate')
}

const textOf = (body) => body ? String(body).replace(/<[^>]*>/g, ' ').replace(/&nbsp;/g, ' ').replace(/\s+/g, ' ').trim() : ''
const summarize = (thread, sortDate) => {
    const messages = thread.messageList
    const deliveryRows = messages.flatMap((message) => message.myRowList.filter((row) => DELIVERY.includes(row.roleTypeId)))
    const unreadCount = messages.filter((message) => message.myRowList.some((row) => DELIVERY.includes(row.roleTypeId) && row.readDate == null)).length
    const isArchived = deliveryRows.length > 0 && deliveryRows.every((row) => row.archivedDate != null)
    if (view === 'archived' && !isArchived) return null
    if (unreadOnly && unreadCount === 0) return null
    const snoozes = deliveryRows.filter((row) => row.archivedDate == null).map((row) => toMillis(row.snoozedThruDate))
            .filter((millis) => millis != null && millis > nowMillis)
    const participants = []
    for (const message of messages) for (const id of [message.fromPartyId].concat(message.toPartyIdList, message.ccPartyIdList, [message.toPartyId])) {
        if (id && !participants.includes(id)) participants.push(id)
    }
    const first = messages[0]
    const last = messages[messages.length - 1]
    const snippet = textOf(last.body)
    const summary = {store: 'internal', threadId: thread.rootCommEventId, rootCommEventId: thread.rootCommEventId,
        lastCommEventId: last.communicationEventId, communicationEventTypeId: (thread.root || first).communicationEventTypeId,
        subject: thread.subject, snippet: snippet.length > 140 ? snippet.substring(0, 137) + '...' : snippet,
        sortDate: sortDate, lastDate: toMillis(last.entryDate), firstDate: toMillis(first.entryDate),
        messageCount: messages.length, replyCount: messages.length - 1, unreadCount: unreadCount, isUnread: unreadCount > 0,
        isFlagged: messages.some((message) => message.myRowList.some((row) => row.isFlagged === 'Y')), isArchived: isArchived,
        snoozedThruDate: snoozes.length ? Math.max.apply(null, snoozes) : null,
        hasAttachment: messages.some((message) => message.attachmentList.length > 0), fromPartyId: last.fromPartyId ?? null,
        participantPartyIdList: participants, participantList: [], contactListId: thread.isMailbox ? thread.contactListId : null,
        contactListName: thread.isMailbox ? thread.contactListName : null, isClosed: thread.isClosed, labelList: labelsOf(messages)}
    return threadFilters.every((filter) => filter(summary, thread)) ? summary : null
}

// scan the view's messages newest first; a thread comes at its newest one
const beforeMillis = toMillis(beforeDate)
const chunkSize = Math.max(pageSize * 2, 50)
const seen = new Set()
const accepted = []
let offset = 0
while (accepted.length <= pageSize) {
    let find = makeFind()
    if (beforeMillis != null) find = find.condition(cf.makeCondition('entryDate', 'less', new Date(beforeMillis)))
    const rows = Array.from(find.orderBy('-entryDate').orderBy('-communicationEventId').offset(offset).limit(chunkSize).list())
    offset += rows.length
    const fresh = []
    for (const row of rows) {
        const threadId = row.rootCommEventId || row.communicationEventId
        if (seen.has(threadId)) continue
        seen.add(threadId)
        fresh.push({threadId: threadId, sortDate: toMillis(row.entryDate)})
    }
    if (fresh.length) {
        // a thread with a message in the view at or after the cursor was on an earlier page
        let shown = new Set()
        if (beforeMillis != null) {
            const ids = fresh.map((candidate) => candidate.threadId)
            shown = new Set(Array.from(makeFind().condition(cf.makeCondition([cf.makeCondition('communicationEventId', 'in', ids),
                cf.makeCondition('rootCommEventId', 'in', ids)], 'or')).condition(cf.makeCondition('entryDate', 'greater-equals',
                new Date(beforeMillis))).list()).map((row) => row.rootCommEventId || row.communicationEventId))
        }
        const candidates = fresh.filter((candidate) => !shown.has(candidate.threadId))
        const threadMap = candidates.length ? ec.service.sync().name('mantle.party.CommunicationServices.get#InternalThreadMessages')
                .parameter('rootCommEventIdList', candidates.map((candidate) => candidate.threadId)).call().threadMap : {}
        if (ec.message.hasError()) return
        for (const candidate of candidates) {
            const thread = threadMap[candidate.threadId]
            const summary = thread ? summarize(thread, candidate.sortDate) : null
            if (summary == null) continue
            accepted.push(summary)
            if (accepted.length > pageSize) break
        }
    }
    if (rows.length < chunkSize) break
}
hasMore = accepted.length > pageSize
threadList = accepted.slice(0, pageSize)
if (hasMore) nextBeforeDate = threadList[threadList.length - 1].sortDate

// the participants' names
const partyIds = Array.from(new Set(threadList.flatMap((thread) => thread.participantPartyIdList)))
if (partyIds.length) {
    const names = {}
    for (const party of ec.entity.find('mantle.party.PartyDetail').condition('partyId', 'in', partyIds).disableAuthz().list())
        names[party.partyId] = party.organizationName || [party.firstName, party.lastName].filter((part) => part).join(' ') || party.partyId
    for (const thread of threadList) thread.participantList = thread.participantPartyIdList.map((id) => ({partyId: id, name: names[id] || id}))
}

const DELIVERY = ['MessageTo', 'MessageCc', 'MessageMailbox']
messageList = []
participantList = []
labelList = []
const partyId = ec.user.userAccount?.partyId || null
if (!partyId) { ec.message.addError('Internal messages need a user with a party'); return }
const wanted = communicationEventId || rootCommEventId
if (!wanted) { ec.message.addError('A communicationEventId or rootCommEventId is required'); return }
if (!rootCommEventId) {
    const event = ec.entity.find('mantle.party.communication.CommunicationEvent').condition('communicationEventId', communicationEventId).one()
    if (event == null) { ec.message.addError(`Communication event ${communicationEventId} not found`); return }
    rootCommEventId = event.rootCommEventId || event.communicationEventId
}
const thread = ec.service.sync().name('mantle.party.CommunicationServices.get#InternalThreadMessages')
        .parameter('rootCommEventIdList', [rootCommEventId]).call().threadMap[rootCommEventId]
if (ec.message.hasError()) return
if (thread == null || (communicationEventId && !thread.messageList.some((message) => message.communicationEventId === communicationEventId))) {
    ec.message.addError(`Communication event ${wanted} not found`); return }
subject = thread.subject
contactListId = thread.isMailbox ? thread.contactListId : null
contactListName = thread.isMailbox ? thread.contactListName : null
isClosed = thread.isClosed
canModerate = thread.canModerate
canReply = !isClosed && (!thread.isMailbox || thread.canPost === true)
unreadCount = 0
const participants = []
for (const message of thread.messageList) {
    const rows = message.myRowList
    const row = rows.find((candidate) => DELIVERY.includes(candidate.roleTypeId)) || rows[0] || null
    const isUnread = rows.some((candidate) => DELIVERY.includes(candidate.roleTypeId) && candidate.readDate == null)
    if (isUnread) unreadCount++
    messageList.push({communicationEventId: message.communicationEventId, parentCommEventId: message.parentCommEventId ?? null,
        rootCommEventId: message.rootCommEventId ?? null, communicationEventTypeId: message.communicationEventTypeId ?? null,
        statusId: message.statusId ?? null, fromPartyId: message.fromPartyId ?? null, toPartyId: message.toPartyId ?? null,
        toPartyIdList: message.toPartyIdList, ccPartyIdList: message.ccPartyIdList, entryDate: message.entryDate ?? null,
        subject: message.subject ?? null, body: message.body ?? null, contentType: message.contentType ?? null,
        contactListId: message.contactListId ?? null, attachmentList: message.attachmentList,
        myState: row == null ? null : {roleTypeId: row.roleTypeId, readDate: row.readDate, isFlagged: row.isFlagged,
            archivedDate: row.archivedDate, snoozedThruDate: row.snoozedThruDate},
        isUnread: isUnread})
    for (const id of [message.fromPartyId].concat(message.toPartyIdList, message.ccPartyIdList, [message.toPartyId])) {
        if (id && !participants.includes(id)) participants.push(id)
    }
}
if (participants.length) {
    const names = {}
    for (const party of ec.entity.find('mantle.party.PartyDetail').condition('partyId', 'in', participants).disableAuthz().list())
        names[party.partyId] = party.organizationName || [party.firstName, party.lastName].filter((part) => part).join(' ') || party.partyId
    participantList = participants.map((id) => ({partyId: id, name: names[id] || id}))
}
const eventIds = messageList.map((message) => message.communicationEventId)
if (eventIds.length) {
    const joins = Array.from(ec.entity.find('mantle.party.communication.CommunicationEventPartyLabel')
            .condition('partyId', partyId).condition('communicationEventId', 'in', eventIds).list())
    const known = {}
    const labelIds = Array.from(new Set(joins.map((row) => row.emailLabelId)))
    if (labelIds.length) for (const label of ec.entity.find('moqui.basic.email.EmailLabel').condition('emailLabelId', 'in', labelIds).list())
        known[label.emailLabelId] = {emailLabelId: label.emailLabelId, labelName: label.labelName ?? null, color: label.color ?? null}
    const byId = new Map()
    for (const row of joins) {
        const label = known[row.emailLabelId]
        if (label) byId.set(label.emailLabelId, label)
    }
    labelList = Array.from(byId.values())
}

const cf = ec.entity.conditionFactory
updatedCount = 0
communicationEventIdList = []
const partyId = ec.user.userAccount?.partyId || null
if (!partyId) { ec.message.addError('Internal messages need a user with a party'); return }
if (!communicationEventId && !rootCommEventId) { ec.message.addError('A communicationEventId or rootCommEventId is required'); return }
const wanted = rootCommEventId || communicationEventId
let scopeIds
if (rootCommEventId) {
    scopeIds = Array.from(ec.entity.find('mantle.party.communication.CommunicationEvent')
            .condition(cf.makeCondition([cf.makeCondition('communicationEventId', 'equals', rootCommEventId),
                cf.makeCondition('rootCommEventId', 'equals', rootCommEventId)], 'or'))
            .selectField('communicationEventId').list()).map((event) => event.communicationEventId)
} else {
    scopeIds = ec.entity.find('mantle.party.communication.CommunicationEvent').condition('communicationEventId', communicationEventId)
            .count() > 0 ? [communicationEventId] : []
}
if (scopeIds.length === 0) { ec.message.addError(`Communication event ${wanted} not found`); return }
const findRows = () => Array.from(ec.entity.find('mantle.party.communication.CommunicationEventParty')
        .condition('communicationEventId', 'in', scopeIds).condition('partyId', partyId).list())
let rows = findRows()
const changesState = read === false || flagged != null || archived != null || snoozedThruDate != null || unsnooze === true
if (rows.length === 0) {
    // no row: visible only through a mailbox (or a message the user sent), and read there
    let rootId = rootCommEventId
    if (!rootId) {
        const event = ec.entity.find('mantle.party.communication.CommunicationEvent').condition('communicationEventId', communicationEventId).one()
        rootId = event.rootCommEventId || event.communicationEventId
    }
    const thread = ec.service.sync().name('mantle.party.CommunicationServices.get#InternalThreadMessages')
            .parameter('rootCommEventIdList', [rootId]).call().threadMap[rootId]
    const visible = thread ? thread.messageList : []
    if (visible.length === 0 || (!rootCommEventId && !visible.some((message) => message.communicationEventId === communicationEventId))) {
        ec.message.addError(`Communication event ${wanted} not found`); return }
    if (!changesState) return
    const posts = visible.filter((message) => message.contactListId && message.contactListId === thread.contactListId && thread.isMailbox &&
            (rootCommEventId || message.communicationEventId === communicationEventId))
    if (posts.length === 0) return
    ec.service.sync().name('create#mantle.party.communication.CommunicationEventParty').parameters({
        communicationEventId: posts[posts.length - 1].communicationEventId, partyId: partyId, roleTypeId: 'MessageMailbox',
        statusId: 'CepReceived', readDate: ec.user.nowTimestamp}).call()
    if (ec.message.hasError()) return
    rows = findRows()
}
const now = ec.user.nowTimestamp
const changed = new Set()
for (const row of rows) {
    if (read === true && row.readDate == null) row.set('readDate', now)
    if (read === false) row.set('readDate', null)
    if (flagged != null) row.set('isFlagged', flagged ? 'Y' : 'N')
    if (archived === true && row.archivedDate == null) row.set('archivedDate', now)
    if (archived === false) row.set('archivedDate', null)
    if (snoozedThruDate != null) row.set('snoozedThruDate', snoozedThruDate)
    if (unsnooze === true) row.set('snoozedThruDate', null)
    row.update()
    updatedCount++
    changed.add(row.communicationEventId)
}
communicationEventIdList = Array.from(changed)

updatedCount = 0
communicationEventIdList = []
const partyId = ec.user.userAccount?.partyId || null
if (!partyId) { ec.message.addError('Internal messages need a user with a party'); return }
if (!communicationEventId && !rootCommEventId) { ec.message.addError('A communicationEventId or rootCommEventId is required'); return }
const asList = (value) => (value == null ? [] : (typeof value === 'string' ? value.split(',') : Array.from(value)))
        .map((id) => String(id).trim()).filter((id) => id)
const addIds = Array.from(new Set(asList(addLabelIdList)))
const removeIds = Array.from(new Set(asList(removeLabelIdList)))
if (addIds.length === 0 && removeIds.length === 0) { ec.message.addError('Name the labels to add or remove'); return }
const wanted = communicationEventId || rootCommEventId
let rootId = rootCommEventId
if (!rootId) {
    const event = ec.entity.find('mantle.party.communication.CommunicationEvent').condition('communicationEventId', communicationEventId).one()
    if (event == null) { ec.message.addError(`Communication event ${communicationEventId} not found`); return }
    rootId = event.rootCommEventId || event.communicationEventId
}
const thread = ec.service.sync().name('mantle.party.CommunicationServices.get#InternalThreadMessages')
        .parameter('rootCommEventIdList', [rootId]).call().threadMap[rootId]
if (ec.message.hasError()) return
if (thread == null || (communicationEventId && !thread.messageList.some((message) => message.communicationEventId === communicationEventId))) {
    ec.message.addError(`Communication event ${wanted} not found`); return }
const scopeIds = communicationEventId && !rootCommEventId ? [communicationEventId]
        : thread.messageList.map((message) => message.communicationEventId)
const accountId = ec.service.sync().name('org.moqui.impl.EmailClientServices.ensure#InternalAccount').call()?.emailAccountId
if (ec.message.hasError()) return
for (const emailLabelId of addIds.concat(removeIds)) {
    const label = ec.entity.find('moqui.basic.email.EmailLabel').condition('emailLabelId', emailLabelId).one()
    if (label == null || label.emailAccountId !== accountId) { ec.message.addError(`Email label ${emailLabelId} not found`); return }
}
const changed = new Set()
const findJoin = (eventId, emailLabelId) => ec.entity.find('mantle.party.communication.CommunicationEventPartyLabel')
        .condition('communicationEventId', eventId).condition('partyId', partyId).condition('emailLabelId', emailLabelId).one()
for (const eventId of scopeIds) {
    for (const emailLabelId of addIds) {
        if (findJoin(eventId, emailLabelId) != null) continue
        const join = ec.entity.makeValue('mantle.party.communication.CommunicationEventPartyLabel')
        join.setFields({communicationEventId: eventId, partyId: partyId, emailLabelId: emailLabelId}, false, null, null)
        join.create()
        updatedCount++
        changed.add(eventId)
    }
    for (const emailLabelId of removeIds) {
        const join = findJoin(eventId, emailLabelId)
        if (join == null) continue
        join.delete()
        updatedCount++
        changed.add(eventId)
    }
}
communicationEventIdList = Array.from(changed)

const findEvent = (id) => ec.entity.find('mantle.party.communication.CommunicationEvent').condition('communicationEventId', id).one()
const event = findEvent(communicationEventId)
if (event == null) { ec.message.addError(`Communication event ${communicationEventId} not found`); return }
rootCommEventId = event.rootCommEventId || event.communicationEventId
const root = rootCommEventId === event.communicationEventId ? event : findEvent(rootCommEventId)
const access = root?.contactListId ? ec.service.sync().name('mantle.marketing.ContactListServices.get#ContactListAccess')
        .parameter('contactListId', root.contactListId).call() : null
if (access == null || !access.isMailbox) { ec.message.addError(`Communication event ${communicationEventId} is not a mailbox post`); return }
if (!access.canModerate) {
    ec.message.addError(access.canReadOwn ? `Only an owner or moderator of ${access.contactList?.contactListName || root.contactListId} may close a thread`
            : `Communication event ${communicationEventId} not found`)
    return
}
// the first post's status, set directly: the status flow has no way back from Resolved
root.set('statusId', reopen ? 'CeReceived' : 'CeResolved')
root.update()
statusId = root.statusId

const cf = ec.entity.conditionFactory
unreadCount = 0
unreadThreadCount = 0
if (!partyId && userId) partyId = ec.entity.find('moqui.security.UserAccount').condition('userId', userId).disableAuthz().one()?.partyId
if (!partyId && !userId) partyId = ec.user.userAccount?.partyId || null
if (!partyId) return
const now = ec.user.nowTimestamp
const rows = Array.from(ec.entity.find('mantle.party.communication.CommunicationEventPartyAndEvent').condition('partyId', partyId)
        .condition('roleTypeId', 'in', ['MessageTo', 'MessageCc', 'MessageMailbox']).condition('readDate', null)
        .condition('archivedDate', null).condition(cf.makeCondition([cf.makeCondition('snoozedThruDate', 'equals', null),
            cf.makeCondition('snoozedThruDate', 'less-equals', now)], 'or'))
        .condition('communicationEventTypeId', 'in', ['Message', 'Comment'])
        .condition(cf.makeCondition('statusId', 'not-equals', 'CeCancelled', true))
        .selectField('communicationEventId').selectField('rootCommEventId').selectField('roleTypeId').selectField('contactListId').list())
if (rows.length === 0) return
// the mailboxes the party takes as Mailbox only
const listIds = Array.from(new Set(rows.filter((row) => row.roleTypeId === 'MessageMailbox' && row.contactListId).map((row) => row.contactListId)))
const mailboxOnly = new Set()
if (listIds.length) {
    const defaults = {}
    for (const list of ec.entity.find('mantle.marketing.contact.ContactList').condition('contactListId', 'in', listIds)
            .selectField('contactListId').selectField('defaultDeliveryEnumId').list()) defaults[list.contactListId] = list.defaultDeliveryEnumId
    for (const row of ec.entity.find('mantle.marketing.contact.ContactListParty').condition('partyId', partyId)
            .condition('contactListId', 'in', listIds).condition('statusId', 'CLPT_ACCEPTED')
            .condition(cf.makeConditionDate('fromDate', 'thruDate', null)).list()) {
        if ((row.deliveryEnumId || defaults[row.contactListId] || 'CldInbox') === 'CldMailboxOnly') mailboxOnly.add(row.contactListId)
    }
}
const messages = new Set()
const threads = new Set()
for (const row of rows) {
    if (row.roleTypeId === 'MessageMailbox' && mailboxOnly.has(row.contactListId)) continue
    messages.add(row.communicationEventId)
    threads.add(row.rootCommEventId || row.communicationEventId)
}
unreadCount = messages.size
unreadThreadCount = threads.size

const toMillis = (value) => {
    if (value == null || value === '') return null
    if (typeof value === 'number') return value
    if (value instanceof Date) return value.getTime()
    const number = Number(value)
    return Number.isNaN(number) ? new Date(String(value)).getTime() : number
}
threadList = []
hasMore = false
nextCursor = null
storeList = []
failedStores = []
termList = []
if (!(pageSize > 0)) pageSize = 50
const STORES = ['email', 'internal']
const EMAIL_VIEWS = ['inbox', 'flagged', 'snoozed', 'scheduled', 'outbox', 'drafts', 'sent', 'archive', 'junk', 'trash', 'all', 'folder', 'label']
// the internal view of each view that has one
const INTERNAL_VIEWS = {inbox: 'received', received: 'received', sent: 'sent', flagged: 'flagged', snoozed: 'snoozed',
    archive: 'archived', archived: 'archived', all: 'all', comments: 'comments'}
const EMAIL_ALIASES = {received: 'inbox', archived: 'archive'}
if (store && !STORES.includes(store)) { ec.message.addError(`Unknown store ${store}: email or internal`); return }
if (view === 'comments') {
    if (store === 'email' || emailFolderId || emailLabelId) { ec.message.addError('The comments view is of the internal messages'); return }
    if (!emailAccountId) store = 'internal'
}

// the search line, read once: the text for the mail, its terms for the internal threads
let searchTerms = null
let internalSearchOff = false
if (searchText && String(searchText).trim()) {
    searchTerms = ec.service.sync().name('org.moqui.impl.EmailClientServices.parse#SearchText').parameter('searchText', searchText).call()
    if (ec.message.hasError()) return
    termList = Array.from(searchTerms.termList || [])
    // a value an operator does not understand is the user's error, not a store that fails
    for (const term of termList) {
        const value = String(term.value)
        if ((term.operator === 'before' || term.operator === 'after') && !/^(\d{4})[\/.-](\d{1,2})[\/.-](\d{1,2})$|^(\d{1,2})\/(\d{1,2})\/(\d{4})$/.test(value)) {
            ec.message.addError(`${term.operator}:${value} needs a date, such as ${term.operator}:2026/10/19`); return }
        if ((term.operator === 'older_than' || term.operator === 'newer_than') && !/^(\d+)\s*([dwmy])$/i.test(value)) {
            ec.message.addError(`${term.operator}:${value} needs a count of days, weeks, months or years, such as ${term.operator}:2d`); return }
        if ((term.operator === 'larger' || term.operator === 'smaller') && !/^(\d+(?:\.\d+)?)\s*([kmg]?)b?$/i.test(value)) {
            ec.message.addError(`${term.operator}:${value} needs a size, such as ${term.operator}:5M`); return }
        if (term.operator === 'in' && term.negate) { ec.message.addError(`-in:${value} is not a search term; in: names one view or folder`); return }
        // in: a view of the internal store too, else the mail only
        if (term.operator === 'in') {
            const IN_INTERNAL = {inbox: 'received', sent: 'sent', flagged: 'flagged', starred: 'flagged', snoozed: 'snoozed', archive: 'archived',
                archived: 'archived', all: 'all', allmail: 'all', 'all mail': 'all', anywhere: 'all'}
            internalSearchOff = !IN_INTERNAL[value.toLowerCase()]
        }
    }
}

// each store's own date, or 'end'
const cursorOf = {}
if (cursor) {
    for (const part of String(cursor).split(',')) {
        const [name, value] = part.split(':')
        if (!STORES.includes(name) || !(value === 'end' || /^\d+$/.test(value || ''))) {
            ec.message.addError(`Not an Inbox cursor: ${cursor}`); return }
        cursorOf[name] = value === 'end' ? 'end' : Number(value)
    }
}

// the stores of the view and their parameters
let emailParameters = null
let internalParameters = null
const emailOnlyFilter = !!(fromAddress || toAddress || subject || hasAttachment != null || fromDate != null || thruDate != null ||
        minSize != null || maxSize != null)
const emailShared = {searchText: searchText, unreadOnly: unreadOnly}
const internalShared = {searchTermMap: searchTerms, unreadOnly: unreadOnly, needsReply: needsReply}
const internalOff = emailOnlyFilter || internalSearchOff
if (contactListId) {
    if (emailAccountId || emailFolderId || emailLabelId || store === 'email') {
        ec.message.addError('A mailbox is listed without an email account, folder or label'); return }
    const access = ec.service.sync().name('mantle.marketing.ContactListServices.get#ContactListAccess')
            .parameter('contactListId', contactListId).call()
    if (ec.message.hasError()) return
    if (!access.exists || !access.isMailbox || !access.canSeeHeader) { ec.message.addError(`Mailbox ${contactListId} not found`); return }
    const internalView = view ? INTERNAL_VIEWS[view] : 'all'
    if (!internalView) { ec.message.addError(`Unknown mailbox view ${view}: received, sent, flagged, snoozed, archived or all`); return }
    if (!internalOff) internalParameters = Object.assign({view: internalView, contactListId: contactListId}, internalShared)
} else {
    // the account, folder and label must be ones the user reaches: an input error, not a store that fails
    let account = null
    let access = null
    if (emailAccountId || emailFolderId || emailLabelId) {
        access = ec.service.sync().name('org.moqui.impl.EmailClientServices.get#EmailAccountAccess')
                .parameters(emailAccountId ? {emailAccountId: emailAccountId} : {}).call()
        if (ec.message.hasError()) return
    }
    if (emailAccountId) {
        if (!(access.level >= 1)) { ec.message.addError(`Email account ${emailAccountId} not found`); return }
        account = access.account
        if (!account.isInternal && store === 'internal') { ec.message.addError(`Email account ${emailAccountId} is not the Internal account`); return }
    }
    if (account?.isInternal || store === 'internal') {
        if (emailFolderId) { ec.message.addError('The Internal account has no folders'); return }
        // view label has no internal counterpart: a label lists every thread the user labeled
        let internalView = INTERNAL_VIEWS[view || (emailLabelId ? 'all' : 'received')]
        if (!internalView && emailLabelId) internalView = 'all'
        if (!internalView && view && !EMAIL_VIEWS.includes(view)) { ec.message.addError(`Unknown view ${view}`); return }
        if (internalView && !internalOff) internalParameters = Object.assign({view: internalView, emailLabelId: emailLabelId || null}, internalShared)
    } else {
        const emailView = view ? (EMAIL_ALIASES[view] || view) : (emailFolderId ? 'folder' : (emailLabelId ? 'label' : 'inbox'))
        if (!EMAIL_VIEWS.includes(emailView)) { ec.message.addError(`Unknown view ${view}: ${EMAIL_VIEWS.join(', ')}`); return }
        if (emailView === 'folder' && !emailFolderId) { ec.message.addError('The folder view needs an emailFolderId'); return }
        if (emailView === 'label' && !emailLabelId) { ec.message.addError('The label view needs an emailLabelId'); return }
        const reaches = (entityName, idField, id, what) => {
            const row = ec.entity.find(entityName).condition(idField, id).one()
            if (row == null || !access.accessMap[row.emailAccountId] || (emailAccountId && row.emailAccountId !== emailAccountId)) {
                ec.message.addError(`${what} ${id} not found`)
                return false
            }
            return true
        }
        if (emailFolderId && !reaches('moqui.basic.email.EmailFolder', 'emailFolderId', emailFolderId, 'Email folder')) return
        let labelRow = null
        if (emailLabelId) {
            labelRow = ec.entity.find('moqui.basic.email.EmailLabel').condition('emailLabelId', emailLabelId).one()
            if (labelRow == null || !access.accessMap[labelRow.emailAccountId] || (emailAccountId && labelRow.emailAccountId !== emailAccountId)) {
                ec.message.addError(`Email label ${emailLabelId} not found`); return }
        }
        const internalAccount = (access?.accountList || []).find((item) => item.isInternal)
        const labelIsInternal = !!(labelRow && internalAccount && labelRow.emailAccountId === internalAccount.emailAccountId)
        // a label of the Internal account is not a mail filter; a mail label is not sent to the internal store
        if (labelIsInternal) {
            if (store === 'email') { ec.message.addError(`Email label ${emailLabelId} not found`); return }
            if (!internalOff) internalParameters = Object.assign({view: INTERNAL_VIEWS[emailView] || 'all', emailLabelId: emailLabelId}, internalShared)
        } else {
            emailParameters = Object.assign({view: emailView, emailAccountId: emailAccountId, emailFolderId: emailFolderId,
                emailLabelId: emailLabelId, threadMode: threadMode, fromAddress: fromAddress, toAddress: toAddress, subject: subject,
                hasAttachment: hasAttachment, fromDate: fromDate, thruDate: thruDate, minSize: minSize, maxSize: maxSize}, emailShared)
            const internalView = INTERNAL_VIEWS[emailView]
            if (!account && !emailFolderId && !emailLabelId && store !== 'email' && internalView && !internalOff)
                internalParameters = Object.assign({view: internalView}, internalShared)
        }
    }
}
const stores = []
if (emailParameters) stores.push({name: 'email', service: 'org.moqui.impl.EmailClientServices.find#Messages', parameters: emailParameters})
if (internalParameters) stores.push({name: 'internal', service: 'mantle.party.CommunicationServices.find#InternalThreads',
    parameters: internalParameters})
storeList = stores.map((entry) => entry.name)
if (stores.length === 0) return

// Needs reply for mail: the thread's newest message in the view is a day old or more, not answered, and nothing
// was sent in the thread after it (a reply waiting in the Outbox counts)
const waitingForReply = (rows) => {
    const cf = ec.entity.conditionFactory
    const dayAgo = toMillis(ec.user.nowTimestamp) - 86400000
    const candidates = rows.filter((row) => toMillis(row.sortDate) <= dayAgo)
    if (candidates.length === 0) return []
    const lastIds = candidates.map((row) => row.emailMessageId)
    const answered = new Set(Array.from(ec.entity.find('moqui.basic.email.EmailMessage').condition('emailMessageId', 'in', lastIds)
            .condition('isAnswered', 'Y').selectField('emailMessageId').list()).map((row) => row.emailMessageId))
    const roots = Array.from(new Set(candidates.map((row) => row.rootEmailMessageId || row.threadId)))
    const sentAt = {}
    for (const message of ec.entity.find('moqui.basic.email.EmailMessage').condition(cf.makeCondition([
            cf.makeCondition('rootEmailMessageId', 'in', roots), cf.makeCondition('emailMessageId', 'in', roots)], 'or'))
            .condition('statusId', 'in', ['ES_SENT', 'ES_SCHEDULED', 'ES_READY']).selectField('emailMessageId')
            .selectField('rootEmailMessageId').selectField('messageDate').selectField('sentDate').list()) {
        const root = message.rootEmailMessageId || message.emailMessageId
        const at = toMillis(message.sentDate || message.messageDate)
        if (at != null && !(sentAt[root] >= at)) sentAt[root] = at
    }
    return candidates.filter((row) => !answered.has(row.emailMessageId) &&
            !(sentAt[row.rootEmailMessageId || row.threadId] > toMillis(row.sortDate)))
}

// pageSize + 1 rows of each store still going, each on its own
const lists = []
for (const entry of stores) {
    if (cursorOf[entry.name] === 'end') continue
    const parameters = Object.assign({}, entry.parameters, {pageSize: pageSize + 1})
    if (cursorOf[entry.name] != null) parameters.beforeDate = new Date(cursorOf[entry.name])
    // in a transaction of its own, so a store that fails does not roll back the other's or the caller's
    ec.message.pushErrors()
    try {
        const out = ec.service.sync().name(entry.service).parameters(parameters).requireNewTransaction(true).call()
        if (ec.message.hasError()) throw new Error(ec.message.getErrorsString())
        if (out == null) throw new Error(`${entry.service} answered nothing`)
        const raw = Array.from(out.threadList || [])
        // a filtered store keeps its row past the page (read to see where a run of one date ends) unfiltered
        const read = raw.length > pageSize ? raw.slice(0, pageSize) : raw
        const rows = entry.name === 'email' && needsReply ? waitingForReply(read) : raw
        lists.push({name: entry.name, raw: raw, rows: rows, hasMore: out.hasMore === true, taken: 0,
            lastRawDate: read.length ? toMillis(read[read.length - 1].sortDate) : null})
    } catch (err) {
        failedStores.push(entry.name)
        ec.logger.error(`Inbox of user ${ec.user.userId}: the ${entry.name} store failed and is left out: ${err && err.message ? err.message : err}`)
    } finally {
        ec.message.clearErrors()
        ec.message.popErrors()
    }
}

// merge by sortDate, newest first; each store's rows stay in its own order
const merged = []
while (merged.length < pageSize) {
    let best = null
    for (const list of lists) {
        if (list.taken >= list.rows.length) continue
        if (best == null || toMillis(list.rows[list.taken].sortDate) > toMillis(best.rows[best.taken].sortDate)) best = list
    }
    if (best == null) break
    merged.push({store: best.name, row: best.rows[best.taken], date: toMillis(best.rows[best.taken].sortDate)})
    best.taken++
}
// a store whose last row kept has the date of its next row would skip the rest of that run on the next page
// (its date is exclusive): end the page before the newest such run
let cutDate = null
const runDate = {}
for (const list of lists) {
    if (list.taken === 0) continue
    // the row read after the last one kept (a row filtered out counts: the next page starts before its date)
    const lastKept = list.rows[list.taken - 1]
    const nextRow = list.raw[list.raw.indexOf(lastKept) + 1]
    if (nextRow === undefined) continue
    const last = toMillis(lastKept.sortDate)
    if (last === toMillis(nextRow.sortDate)) {
        runDate[list.name] = last
        if (cutDate == null || last > cutDate) cutDate = last
    }
}
let page = merged
if (cutDate != null) {
    const kept = merged.filter((entry) => entry.date > cutDate || (entry.date === cutDate && runDate[entry.store] !== cutDate))
    if (kept.length) page = kept
    else ec.logger.warn(`Inbox of user ${ec.user.userId}: more than ${pageSize} rows of one store have sortDate ${cutDate}; the next page starts after them`)
}

// each store's next date
const nextOf = {}
for (const entry of stores) {
    const name = entry.name
    if (cursorOf[name] === 'end') { nextOf[name] = 'end'; continue }
    // a store that failed keeps its date, for the next page to try again
    if (failedStores.includes(name)) { if (cursorOf[name] != null) nextOf[name] = cursorOf[name]; continue }
    const list = lists.find((candidate) => candidate.name === name)
    const keptRows = page.filter((candidate) => candidate.store === name)
    if (keptRows.length === list.rows.length && !list.hasMore) { nextOf[name] = 'end'; continue }
    if (keptRows.length) nextOf[name] = keptRows[keptRows.length - 1].date
    // every row read was filtered out (needsReply): the next page reads after them
    else if (list.rows.length === 0 && list.lastRawDate != null) nextOf[name] = list.lastRawDate
    else if (cursorOf[name] != null) nextOf[name] = cursorOf[name]
    hasMore = true
}
if (hasMore) nextCursor = Object.keys(nextOf).map((name) => `${name}:${nextOf[name]}`).join(',')

const byMessage = emailParameters != null && threadMode === false
threadList = page.map((entry) => Object.assign({}, entry.row, {rowKey: `${entry.store}:${entry.store === 'email' && byMessage
        ? entry.row.emailMessageId : entry.row.threadId}`}))

accountList = []
mailboxList = []
internalEmailAccountId = null
emailUnreadCount = null
internalUnreadCount = null
internalUnreadThreadCount = null
unifiedUnreadCount = null
failedParts = []
const part = (name, run) => {
    ec.message.pushErrors()
    try {
        run()
        if (ec.message.hasError()) throw new Error(ec.message.getErrorsString())
        return true
    } catch (err) {
        failedParts.push(name)
        ec.logger.error(`Inbox counts of user ${ec.user.userId}: the ${name} part failed and is left out: ${err && err.message ? err.message : err}`)
        return false
    } finally {
        ec.message.clearErrors()
        ec.message.popErrors()
    }
}
// each part in a transaction of its own, so one that fails does not roll back the others
const callService = (name, parameters) => {
    const out = ec.service.sync().name(name).parameters(parameters || {}).requireNewTransaction(true).call()
    if (ec.message.hasError()) throw new Error(ec.message.getErrorsString())
    if (out == null) throw new Error(`${name} answered nothing`)
    return out
}
const emailOk = part('email', () => {
    const out = callService('org.moqui.impl.EmailClientServices.get#UserEmailAccounts')
    accountList = Array.from(out.accountList || []).map((account) => Object.assign({}, account))
    internalEmailAccountId = out.internalEmailAccountId ?? null
    emailUnreadCount = accountList.filter((account) => !account.isInternal).reduce((sum, account) => sum + (account.unreadCount || 0), 0)
})
const internalOk = part('internal', () => {
    const out = callService('mantle.party.CommunicationServices.count#UnreadInternalMessages')
    internalUnreadCount = out.unreadCount ?? 0
    internalUnreadThreadCount = out.unreadThreadCount ?? 0
})
for (const account of accountList) if (account.isInternal) account.unreadCount = internalOk ? internalUnreadCount : null
part('mailboxes', () => {
    const out = callService('mantle.marketing.ContactListServices.find#ContactLists', {contactListTypeEnumId: 'MAILBOX', memberOnly: true})
    mailboxList = Array.from(out.contactListList || []).map((list) => ({contactListId: list.contactListId,
        contactListName: list.contactListName ?? null, isMember: list.isMember === true, membershipStatusId: list.membershipStatusId ?? null,
        deliveryEnumId: list.deliveryEnumId || list.defaultDeliveryEnumId || 'CldInbox', unreadCount: list.unreadCount ?? 0,
        lastPostDate: list.lastPostDate ?? null}))
})
if (emailOk && internalOk) unifiedUnreadCount = emailUnreadCount + internalUnreadCount

const cf = ec.entity.conditionFactory
notifiedUserIds = []
coalescedUserIds = []
newCount = 0
const textOf = (body) => body ? String(body).replace(/<[^>]*>/g, ' ').replace(/&nbsp;/g, ' ').replace(/\s+/g, ' ').trim() : ''
const summaryOf = (subjectText, body) => {
    const text = textOf(body)
    return subjectText || (text.length > 120 ? text.substring(0, 117) + '...' : text)
}
ec.message.pushErrors()
try {
    let userIds = []
    let message = null
    let record = null
    let actorUserId = null
    let earlier = false
    if (emailMessageId) {
        const email = ec.entity.find('moqui.basic.email.EmailMessage').condition('emailMessageId', emailMessageId).disableAuthz().one()
        if (email == null || !email.emailAccountId || email.statusId !== 'ES_RECEIVED' || email.isRead === 'Y' || email.archivedDate != null) return
        if (email.snoozedThruDate != null && Number(email.snoozedThruDate) > Number(ec.user.nowTimestamp)) return
        const folder = email.emailFolderId ? ec.entity.find('moqui.basic.email.EmailFolder').condition('emailFolderId', email.emailFolderId)
                .disableAuthz().one() : null
        if (folder == null || folder.folderKindEnumId !== 'EfkInbox') return
        const account = ec.entity.find('moqui.basic.email.EmailAccount').condition('emailAccountId', email.emailAccountId).disableAuthz().one()
        if (account == null || account.statusId === 'EasRemoved') return
        const users = new Set(account.ownerUserId ? [account.ownerUserId] : [])
        for (const row of ec.entity.find('moqui.basic.email.EmailAccountUser').condition('emailAccountId', email.emailAccountId)
                .conditionDate('fromDate', 'thruDate', null).disableAuthz().list()) users.add(row.userId)
        userIds = Array.from(users)
        // the burst this message is in: the account's unread received mail in an Inbox stored within the window
        newCount = 1
        const windowMillis = (coalesceSeconds == null ? 15 : Number(coalesceSeconds)) * 1000
        const stampOf = (row) => {
            const value = row.lastUpdatedStamp
            if (value == null || value === '') return null
            if (value instanceof Date) return value.getTime()
            const number = Number(value)
            return Number.isNaN(number) ? new Date(String(value)).getTime() : number
        }
        const stamp = stampOf(email)
        if (windowMillis > 0 && stamp != null) {
            const inboxIds = Array.from(ec.entity.find('moqui.basic.email.EmailFolder').condition('emailAccountId', email.emailAccountId)
                    .condition('folderKindEnumId', 'EfkInbox').selectField('emailFolderId').disableAuthz().list()).map((row) => row.emailFolderId)
            const before = (row) => {
                const other = stampOf(row)
                if (other !== stamp) return other < stamp
                const left = String(row.emailMessageId), right = String(emailMessageId)
                return left.length !== right.length ? left.length < right.length : left < right
            }
            const burst = Array.from(ec.entity.find('moqui.basic.email.EmailMessage').condition('emailAccountId', email.emailAccountId)
                    .condition('emailFolderId', 'in', inboxIds).condition('statusId', 'ES_RECEIVED')
                    .condition(cf.makeCondition('isRead', 'not-equals', 'Y', true)).condition('archivedDate', null)
                    .condition('emailMessageId', 'not-equals', emailMessageId)
                    .condition(cf.makeCondition('lastUpdatedStamp', 'greater-equals', new Date(stamp - windowMillis)))
                    .condition(cf.makeCondition('lastUpdatedStamp', 'less-equals', new Date(stamp + windowMillis)))
                    .selectField('emailMessageId').selectField('lastUpdatedStamp').disableAuthz().list())
            earlier = burst.some(before)
            newCount = 1 + burst.filter((row) => !before(row)).length
        }
        message = {store: 'email', emailMessageId: emailMessageId, threadId: email.rootEmailMessageId || emailMessageId,
            emailAccountId: email.emailAccountId, accountName: account.accountName ?? null, contactListId: null, contactListName: null,
            fromName: email.fromName || email.fromAddress || '', fromAddress: email.fromAddress ?? null, subject: email.subject ?? '',
            summary: email.snippet || summaryOf(email.subject, email.bodyText || email.body), newCount: newCount}
        record = ['moqui.basic.email.EmailMessage', emailMessageId]
    } else if (communicationEventId) {
        const event = ec.entity.find('mantle.party.communication.CommunicationEvent').condition('communicationEventId', communicationEventId)
                .disableAuthz().one()
        if (event == null || event.communicationEventTypeId !== 'Message' || event.statusId === 'CeCancelled') return
        const rows = Array.from(ec.entity.find('mantle.party.communication.CommunicationEventParty')
                .condition('communicationEventId', communicationEventId).condition('roleTypeId', 'in', ['MessageTo', 'MessageCc', 'MessageMailbox'])
                .disableAuthz().list())
        // a member who takes the mailbox as Mailbox only reads the post there
        const mailboxOnly = new Set()
        let contactListName = null
        if (event.contactListId) {
            const list = ec.entity.find('mantle.marketing.contact.ContactList').condition('contactListId', event.contactListId).disableAuthz().one()
            contactListName = list?.contactListName ?? null
            for (const member of ec.entity.find('mantle.marketing.contact.ContactListParty').condition('contactListId', event.contactListId)
                    .condition('statusId', 'CLPT_ACCEPTED').condition(cf.makeConditionDate('fromDate', 'thruDate', null)).disableAuthz().list()) {
                if ((member.deliveryEnumId || list?.defaultDeliveryEnumId || 'CldInbox') === 'CldMailboxOnly') mailboxOnly.add(member.partyId)
            }
        }
        const partyIds = Array.from(new Set(rows.filter((row) => !(row.roleTypeId === 'MessageMailbox' && mailboxOnly.has(row.partyId)))
                .map((row) => row.partyId).filter((partyId) => partyId !== event.fromPartyId)))
        if (partyIds.length === 0) return
        const senders = new Set(event.fromPartyId ? Array.from(ec.entity.find('moqui.security.UserAccount').condition('partyId', event.fromPartyId)
                .selectField('userId').disableAuthz().list()).map((account) => account.userId) : [])
        userIds = Array.from(new Set(Array.from(ec.entity.find('moqui.security.UserAccount').condition('partyId', 'in', partyIds)
                .selectField('userId').disableAuthz().list()).map((account) => account.userId))).filter((userId) => !senders.has(userId))
        let fromName = ''
        if (event.fromPartyId) {
            const party = ec.entity.find('mantle.party.PartyDetail').condition('partyId', event.fromPartyId).disableAuthz().one()
            fromName = party ? (party.organizationName || [party.firstName, party.lastName].filter((part) => part).join(' ') || event.fromPartyId) : event.fromPartyId
        }
        message = {store: 'internal', communicationEventId: communicationEventId, threadId: event.rootCommEventId || communicationEventId,
            emailAccountId: null, contactListId: event.contactListId ?? null, contactListName: contactListName, fromName: fromName,
            fromAddress: null, subject: event.subject ?? '', summary: summaryOf(event.subject, event.body)}
        record = ['mantle.party.communication.CommunicationEvent', communicationEventId]
        actorUserId = senders.size ? Array.from(senders)[0] : null
        newCount = 1
        message.newCount = 1
    } else {
        return
    }
    if (userIds.length === 0) return
    // a message after the first of its burst: the burst's alert is the first one's
    if (earlier) { coalescedUserIds = userIds; newCount = 0; return }
    const nm = ec.makeNotificationMessage().topic('NewMail').message(message).userIds(userIds).record(record[0], record[1])
    if (actorUserId) nm.actorUserId(actorUserId)
    nm.send()
    notifiedUserIds = Array.from(nm.getNotifyUserIds() ?? [])
} catch (err) {
    ec.logger.error(`New mail alert for ${emailMessageId ? 'email message ' + emailMessageId : 'communication event ' + communicationEventId} not sent: ${err && err.message ? err.message : err}`)
    notifiedUserIds = []
} finally {
    if (ec.message.hasError()) ec.logger.error(`New mail alert for ${emailMessageId || communicationEventId}: ${ec.message.getErrorsString()}`)
    ec.message.clearErrors()
    ec.message.popErrors()
}

service-call.in-map:
{communicationEventTypeId:'Comment', contactMechTypeEnumId:'CmtWebForm', statusId:'CeSent',
                        fromPartyId:ec.user.userAccount.partyId, entryDate:ec.user.nowTimestamp,
                        contentType:contentType, subject:subject, body:body}

actions.script:
isClient = false
visibleWorkEffortIds = []; visibleRequestIds = []; visibleCommunicationEventIds = []
const client = ec.service.sync().name('mantle.work.ProjectServices.get#ClientProjectInfo').parameter('userId', userId || null).call()
if (ec.message.hasError()) return
isClient = !!client?.isClient
if (!isClient || !client.userPartyId) return
const listOf = (value) => value == null ? [] : (typeof value === 'string' ? value.split(',') : Array.from(value))
        .map((id) => String(id).trim()).filter((id) => id)
const projects = new Set(Array.from(client.clientProjectIds || []))
const me = client.userPartyId
const orgSide = new Set(Array.from(client.clientContactPartyIds || []).concat(Array.from(client.clientOrgIds || [])))
const updates = new Set(Array.from(client.statusUpdateIds || []))
const shared = ['WevAllUsers', 'WevGeneral']
const cf = ec.entity.conditionFactory
const wasDisabled = ec.artifactExecution.disableAuthz()
try {
    const workEffortSeen = new Map()
    const workEffortVisible = (ids) => {
        const wanted = ids.filter((id) => !workEffortSeen.has(id))
        if (wanted.length) {
            for (const id of wanted) workEffortSeen.set(id, false)
            for (const row of ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', 'in', wanted)
                    .selectField('workEffortId').selectField('workEffortTypeEnumId').selectField('rootWorkEffortId')
                    .selectField('visibilityEnumId').list()) {
                let seen = false
                if (row.workEffortTypeEnumId === 'WetProject') seen = projects.has(row.workEffortId)
                else if (row.workEffortTypeEnumId === 'WetTask') seen = projects.has(row.rootWorkEffortId) && shared.includes(row.visibilityEnumId)
                else if (['WetMilestone', 'WetRelease'].includes(row.workEffortTypeEnumId)) seen = projects.has(row.rootWorkEffortId)
                workEffortSeen.set(row.workEffortId, seen)
            }
        }
        return ids.filter((id) => workEffortSeen.get(id))
    }
    const requestSeen = new Map()
    const requestVisible = (ids) => {
        const wanted = ids.filter((id) => !requestSeen.has(id))
        if (wanted.length) {
            for (const id of wanted) requestSeen.set(id, false)
            const rows = Array.from(ec.entity.find('mantle.request.Request').condition('requestId', 'in', wanted)
                    .selectField('requestId').selectField('filedByPartyId').selectField('rootWorkEffortId').list())
            const inProject = rows.filter((row) => row.filedByPartyId !== me && projects.has(row.rootWorkEffortId)).map((row) => row.requestId)
            const byParty = new Set(inProject.length && orgSide.size ? Array.from(ec.entity.find('mantle.request.RequestParty')
                    .condition('requestId', 'in', inProject).condition('partyId', 'in', Array.from(orgSide))
                    .condition(cf.makeConditionDate('fromDate', 'thruDate', null)).selectField('requestId').list()).map((row) => row.requestId) : [])
            for (const row of rows) requestSeen.set(row.requestId, row.filedByPartyId === me
                    || (projects.has(row.rootWorkEffortId) && (orgSide.has(row.filedByPartyId) || byParty.has(row.requestId))))
        }
        return ids.filter((id) => requestSeen.get(id))
    }
    visibleWorkEffortIds = workEffortVisible(listOf(workEffortIds))
    visibleRequestIds = requestVisible(listOf(requestIds))

    const eventIds = listOf(communicationEventIds)
    if (!eventIds.length) return
    const events = Array.from(ec.entity.find('mantle.party.communication.CommunicationEvent').condition('communicationEventId', 'in', eventIds).list())
    const partiesOf = new Map()
    for (const row of ec.entity.find('mantle.party.communication.CommunicationEventParty').condition('communicationEventId', 'in', eventIds)
            .selectField('communicationEventId').selectField('partyId').list()) {
        if (!partiesOf.has(row.communicationEventId)) partiesOf.set(row.communicationEventId, new Set())
        partiesOf.get(row.communicationEventId).add(row.partyId)
    }
    // whether an event (or the root of its thread) is filed on a work effort or request the client sees
    const onClientRecord = (event) => {
        const ids = [event.communicationEventId]
        if (event.rootCommEventId && event.rootCommEventId !== event.communicationEventId) ids.push(event.rootCommEventId)
        const workIds = Array.from(ec.entity.find('mantle.work.effort.WorkEffortCommEvent').condition('communicationEventId', 'in', ids)
                .selectField('workEffortId').list()).map((row) => row.workEffortId)
        const requestIdList = Array.from(ec.entity.find('mantle.request.RequestCommEvent').condition('communicationEventId', 'in', ids)
                .selectField('requestId').list()).map((row) => row.requestId)
        for (const row of ec.entity.find('mantle.party.communication.CommunicationEventRecord').condition('communicationEventId', 'in', ids)
                .condition('recordEntityName', 'in', ['mantle.work.effort.WorkEffort', 'mantle.request.Request']).list()) {
            if (row.recordEntityName === 'mantle.work.effort.WorkEffort') workIds.push(row.recordId)
            else requestIdList.push(row.recordId)
        }
        return workEffortVisible(workIds).length > 0 || requestVisible(requestIdList).length > 0
    }
    for (const event of events) {
        const id = event.communicationEventId
        if (event.statusId === 'CeCancelled') continue
        if (event.communicationEventTypeId === 'StatusUpdate') { if (updates.has(id)) visibleCommunicationEventIds.push(id); continue }
        if (!event.communicationEventTypeId || event.communicationEventTypeId === 'Comment') continue
        const parties = new Set(partiesOf.get(id) || [])
        if (event.fromPartyId) parties.add(event.fromPartyId)
        if (event.toPartyId) parties.add(event.toPartyId)
        if (parties.has(me)) { visibleCommunicationEventIds.push(id); continue }
        if (Array.from(parties).some((partyId) => orgSide.has(partyId)) && onClientRecord(event)) visibleCommunicationEventIds.push(id)
    }
} finally {
    if (!wasDisabled) ec.artifactExecution.enableAuthz()
}

const commEventJoins = {
    'mantle.order.OrderHeader': {entityName: 'mantle.order.OrderCommunicationEvent', keyField: 'orderId'},
    'mantle.request.Request': {entityName: 'mantle.request.RequestCommEvent', keyField: 'requestId'},
    'mantle.work.effort.WorkEffort': {entityName: 'mantle.work.effort.WorkEffortCommEvent', keyField: 'workEffortId'},
    'moqui.resource.wiki.WikiPage': {entityName: 'mantle.party.communication.WikiPageCommunicationEvent', keyField: 'wikiPageId'}}
const workEffortJoins = {
    'mantle.request.Request': {entityName: 'mantle.request.RequestWorkEffort', keyField: 'requestId'},
    'moqui.resource.wiki.WikiPage': {entityName: 'mantle.work.effort.WikiPageWorkEffort', keyField: 'wikiPageId'}}
const requestJoins = {
    'mantle.work.effort.WorkEffort': {entityName: 'mantle.request.RequestWorkEffort', keyField: 'workEffortId'},
    'moqui.resource.wiki.WikiPage': {entityName: 'mantle.request.WikiPageRequest', keyField: 'wikiPageId'}}
const noteEntities = {
    'mantle.party.Party': {entityName: 'mantle.party.PartyNote', keyField: 'partyId'},
    'mantle.work.effort.WorkEffort': {entityName: 'mantle.work.effort.WorkEffortNote', keyField: 'workEffortId'},
    'mantle.request.Request': {entityName: 'mantle.request.RequestNote', keyField: 'requestId'},
    'mantle.order.OrderHeader': {entityName: 'mantle.order.OrderNote', keyField: 'orderId'},
    'mantle.facility.Facility': {entityName: 'mantle.facility.FacilityNote', keyField: 'facilityId'}}
// the record types with a *Content entity: the 13 with create and save services, and Facility
const content = (entityName, keyField, typeField, dateField) =>
        ({entityName: entityName, keyField: keyField, typeField: typeField, dateField: dateField || 'contentDate'})
const contentEntities = {
    'mantle.party.agreement.Agreement': content('mantle.party.agreement.AgreementContent', 'agreementId', 'contentTypeEnumId'),
    'mantle.product.maintenance.AssetMaintenance': content('mantle.product.maintenance.AssetMaintenanceContent',
            'assetMaintenanceId', 'contentTypeEnumId'),
    'mantle.party.communication.CommunicationEvent': content('mantle.party.communication.CommunicationEventContent',
            'communicationEventId', 'contentTypeEnumId'),
    'mantle.account.invoice.Invoice': content('mantle.account.invoice.InvoiceContent', 'invoiceId', 'contentTypeEnumId'),
    'mantle.order.OrderHeader': content('mantle.order.OrderContent', 'orderId', 'orderContentTypeEnumId'),
    'mantle.party.Party': content('mantle.party.PartyContent', 'partyId', 'partyContentTypeEnumId'),
    'mantle.account.payment.Payment': content('mantle.account.payment.PaymentContent', 'paymentId', 'contentTypeEnumId'),
    'mantle.account.method.PaymentMethod': content('mantle.account.method.PaymentMethodContent', 'paymentMethodId', 'contentTypeEnumId'),
    'mantle.product.Product': content('mantle.product.ProductContent', 'productId', 'productContentTypeEnumId', 'fromDate'),
    'mantle.product.category.ProductCategory': content('mantle.product.category.ProductCategoryContent',
            'productCategoryId', 'categoryContentTypeEnumId', 'fromDate'),
    'mantle.request.Request': content('mantle.request.RequestContent', 'requestId', 'contentTypeEnumId'),
    'mantle.shipment.Shipment': content('mantle.shipment.ShipmentContent', 'shipmentId', 'shipmentContentTypeEnumId'),
    'mantle.work.effort.WorkEffort': content('mantle.work.effort.WorkEffortContent', 'workEffortId', 'contentTypeEnumId'),
    'mantle.facility.Facility': content('mantle.facility.FacilityContent', 'facilityId', 'facilityContentTypeEnumId')}

const PARTY = 'mantle.party.Party'
const WORK_EFFORT = 'mantle.work.effort.WorkEffort'
const REQUEST = 'mantle.request.Request'
const COMM_EVENT = 'mantle.party.communication.CommunicationEvent'
const ORDER = 'mantle.order.OrderHeader'
const WIKI_PAGE = 'moqui.resource.wiki.WikiPage'
const GIT_MERGE_REQUEST = 'moqui.resource.GitMergeRequest'
const GIT_REPOSITORY = 'moqui.resource.GitRepository'
const TIMESHEET = 'mantle.work.time.Timesheet'
recordVisible = null
notVisibleReason = null
// a refusal: an error, or with checkOnly the answer false
const refuse = (message) => {
    if (checkOnly) { recordVisible = false; notVisibleReason = message }
    else ec.message.addError(message)
}

let recordValue
try { recordValue = ec.entity.makeValue(recordEntityName) }
catch (err) { refuse(`The record type ${recordEntityName} is not an entity`); return }
recordEntityName = recordValue.getEntityName()
recordTypeName = recordValue.getEntityNamePretty()
const keyNames = Object.keys(recordValue.getPrimaryKeys())
if (keyNames.length !== 1) {
    refuse(`The record type ${recordEntityName} has ${keyNames.length} primary key fields, a record link needs one`)
    return
}
recordKeyField = keyNames[0]
isParty = recordEntityName === PARTY
commEventJoin = commEventJoins[recordEntityName] || null
workEffortJoin = workEffortJoins[recordEntityName] || null
requestJoin = requestJoins[recordEntityName] || null
noteEntity = noteEntities[recordEntityName] || null
contentEntity = contentEntities[recordEntityName] || null
if (!checkRecord && !checkOnly) return

// ===== whether the user may see the record (see the description) =====
const cf = ec.entity.conditionFactory
const authzOn = !ec.artifactExecution.authzDisabled()
const current = () => cf.makeConditionDate('fromDate', 'thruDate', null)

// the user's party and the organizations of the organization filter (orgIds null: no organization filter)
let scope = null
const userScope = () => {
    if (scope) return scope
    const userPartyId = ec.user.userAccount?.partyId || null
    let orgIds = null
    if (authzOn) {
        if (userPartyId && ec.user.context.filterOrgIds === undefined)
            ec.service.sync().name('mantle.party.PartyServices.setup#UserOrganizationInfo').call()
        const filterSets = () => new Set(Array.from(ec.artifactExecution.getFindFiltersForUser(PARTY) || [])
                .map((filter) => filter.entityFilterSetId))
        const activeOrgId = ec.user.context.activeOrgId || null
        const filterOrgIds = Array.from(ec.user.context.filterOrgIds || [])
        let sets = filterSets()
        if (sets.has('MANTLE_USER_ORG')) orgIds = filterOrgIds
        else if (sets.has('MANTLE_ACTIVE_ORG')) orgIds = activeOrgId ? [activeOrgId] : filterOrgIds
        else if (!activeOrgId) {
            // MANTLE_ACTIVE_ORG applies only with an active organization (its applyCond): whether the
            // authorization names it is asked with one in the user context for the moment
            const hadActive = 'activeOrgId' in ec.user.context
            const oldActive = ec.user.context.activeOrgId
            ec.user.context.activeOrgId = '_NA_'
            try { sets = filterSets() } finally {
                if (hadActive) ec.user.context.activeOrgId = oldActive ?? null
                else delete ec.user.context.activeOrgId
            }
            if (sets.has('MANTLE_ACTIVE_ORG')) orgIds = filterOrgIds
        }
    }
    scope = {userPartyId: userPartyId, orgIds: orgIds, partyIds: (userPartyId ? [userPartyId] : []).concat(orgIds || [])}
    return scope
}
// the mailboxes whose every post the user may read, and the others
let mailboxes = null
const mailboxAccess = () => {
    if (mailboxes) return mailboxes
    const out = ec.service.sync().name('mantle.marketing.ContactListServices.get#UserMailboxAccess')
            .parameter('partyId', userScope().userPartyId).call()
    mailboxes = {readable: Array.from(out?.readableContactListIds || []), hidden: Array.from(out?.hiddenContactListIds || [])}
    return mailboxes
}
// staff: ADMIN, or an explicit entity authorization for the record type (not the inherited one of an app root)
const staff = {}
const staffSees = (entityName) => {
    if (Object.prototype.hasOwnProperty.call(staff, entityName)) return staff[entityName]
    let sees = false
    try {
        if (ec.user.isInGroup('ADMIN')) {
            sees = true
        } else {
            const groupIds = Array.from(ec.user.getUserGroupIdSet() || [])
            const rows = Array.from(ec.entity.find('moqui.security.ArtifactAuthzCheckView').condition('userGroupId', 'in', groupIds)
                    .condition('artifactTypeEnumId', 'AT_ENTITY').condition('authzActionEnumId', 'in', ['AUTHZA_ALL', 'AUTHZA_VIEW'])
                    .disableAuthz().list()).filter((row) => {
                if (row.nameIsPattern !== 'Y') return row.artifactName === entityName
                try { return new RegExp(`^(?:${row.artifactName})$`).test(entityName) }
                catch (err) {
                    ec.logger.error(`Artifact authz ${row.artifactAuthzId}: the pattern ${row.artifactName} is not valid, skipped: ${err}`)
                    return false
                }
            })
            sees = rows.some((row) => row.authzTypeEnumId === 'AUTHZT_ALLOW' || row.authzTypeEnumId === 'AUTHZT_ALWAYS')
                    && !rows.some((row) => row.authzTypeEnumId === 'AUTHZT_DENY')
                    && ec.artifactExecution.isPermitted(entityName, 'AT_ENTITY', 'view')
        }
    } catch (err) {
        ec.logger.error(`Record visibility: the entity authorization of user ${ec.user.userId} for ${entityName} was not read, ` +
                `the per-user rules apply: ${err}`)
        sees = false
    }
    staff[entityName] = sees
    return sees
}

const workEffortVisible = (workEffort, s) => {
    if (s.partyIds.length === 0) return false
    const ids = [workEffort.workEffortId]
    let root = null
    if (workEffort.rootWorkEffortId && workEffort.rootWorkEffortId !== workEffort.workEffortId) {
        ids.push(workEffort.rootWorkEffortId)
        root = ec.entity.find(WORK_EFFORT).condition('workEffortId', workEffort.rootWorkEffortId).disableAuthz().one()
    }
    if ([workEffort.ownerPartyId, root?.ownerPartyId].some((partyId) => partyId && s.partyIds.includes(partyId))) return true
    if (ec.entity.find('mantle.work.effort.WorkEffortParty').condition('workEffortId', 'in', ids)
            .condition('partyId', 'in', s.partyIds).condition(current()).disableAuthz().count() > 0) return true
    // an event the user sees on the calendar: visible to all users, or in a calendar the user may view (an
    // instance changed on its own is in its series' calendars)
    if (workEffort.visibilityEnumId === 'WevAllUsers') return true
    const calendarOf = ids.concat(Array.from(ec.entity.find('mantle.work.effort.WorkEffortAssoc').condition('toWorkEffortId', workEffort.workEffortId)
            .condition('workEffortAssocTypeEnumId', 'WeatRecurrenceInstance').disableAuthz().list()).map((assoc) => assoc.workEffortId))
    const calendarIds = Array.from(new Set(Array.from(ec.entity.find('mantle.work.calendar.CalendarWorkEffort')
            .condition('workEffortId', 'in', calendarOf).disableAuthz().list()).map((row) => row.calendarId)))
    if (!calendarIds.length) return false
    const access = ec.service.sync().name('mantle.work.CalendarServices.check#CalendarAccess')
            .parameters({calendarIdList: calendarIds}).disableAuthz().call()
    return calendarIds.some((id) => ['CalpView', 'CalpEdit', 'CalpManage'].includes(access?.permissionMap?.[id]))
}
const requestVisible = (request, s) => {
    if (s.userPartyId && request.filedByPartyId === s.userPartyId) return true
    if (s.partyIds.length && ec.entity.find('mantle.request.RequestParty').condition('requestId', request.requestId)
            .condition('partyId', 'in', s.partyIds).condition(current()).disableAuthz().count() > 0) return true
    // IronStone Projects: a request of a project the user sees
    if (request.rootWorkEffortId) {
        const vis = ec.service.sync().name('mantle.work.ProjectServices.get#VisibleProjectInfo').call() || {}
        if (vis.allProjects || Array.from(vis.visibleProjectIds || []).includes(request.rootWorkEffortId)) return true
    }
    if (s.orgIds.length === 0) return false
    const store = request.productStoreId ? ec.entity.find('mantle.product.store.ProductStore')
            .condition('productStoreId', request.productStoreId).disableAuthz().one() : null
    if (store?.organizationPartyId && s.orgIds.includes(store.organizationPartyId)) return true
    const facility = request.facilityId ? ec.entity.find('mantle.facility.Facility')
            .condition('facilityId', request.facilityId).disableAuthz().one() : null
    if (facility?.ownerPartyId && s.orgIds.includes(facility.ownerPartyId)) return true
    // IronStone Projects: one with no project, of a type the user's organization triages in Projects (its ProjIntake)
    if (request.rootWorkEffortId || !request.requestTypeEnumId) return false
    for (const setting of ec.entity.find('mantle.party.PartySetting').condition('partyId', 'in', s.orgIds)
            .condition('partySettingTypeId', 'ProjIntake').disableAuthz().list()) {
        const triaged = ec.service.sync().name('mantle.request.RequestServices.get#IntakeSettings')
                .parameter('organizationPartyId', setting.partyId).disableAuthz().call()?.settings?.triagedTypes || []
        if (Array.from(triaged).includes(request.requestTypeEnumId)) return true
    }
    return false
}
const orderVisible = (order, s) => {
    if (s.userPartyId && order.enteredByPartyId === s.userPartyId) return true
    if (s.partyIds.length === 0) return false
    // a part of the user's party or organizations as vendor or customer, as the OrderPart filter has it
    if (Array.from(ec.entity.find('mantle.order.OrderPart').condition('orderId', order.orderId).disableAuthz().list())
            .some((part) => s.partyIds.includes(part.vendorPartyId) || s.partyIds.includes(part.customerPartyId))) return true
    return ec.entity.find('mantle.order.OrderPartParty').condition('orderId', order.orderId)
            .condition('partyId', 'in', s.partyIds).disableAuthz().count() > 0
}
// the wiki's own view rule, org.moqui.impl.WikiServices.get#WikiPageAccess (see the description), once a page
const wikiViews = {}
const wikiPageVisible = (page) => {
    const pageId = page.wikiPageId
    if (!Object.prototype.hasOwnProperty.call(wikiViews, pageId)) wikiViews[pageId] = !!ec.service.sync()
            .name('org.moqui.impl.WikiServices.get#WikiPageAccess').parameter('wikiPageId', pageId).call()?.canView
    return wikiViews[pageId]
}
let visible
const commEventVisible = (commEvent, depth) => {
    const s = userScope()
    const mailbox = commEvent.contactListId ? mailboxAccess() : null
    const hiddenPost = !!(mailbox && mailbox.hidden.includes(commEvent.contactListId))
    const eventIds = [commEvent.communicationEventId]
    if (commEvent.rootCommEventId && commEvent.rootCommEventId !== commEvent.communicationEventId) eventIds.push(commEvent.rootCommEventId)
    // a comment on a wiki page the user may not see, the event's or its thread root's, is kept as a mailbox post is
    const onHiddenWikiPage = () => Array.from(ec.entity.find('mantle.party.communication.WikiPageCommunicationEvent')
            .condition('communicationEventId', 'in', eventIds).disableAuthz().list()).some((row) => {
        const page = ec.entity.find(WIKI_PAGE).condition('wikiPageId', row.wikiPageId).disableAuthz().one()
        return page == null || !wikiPageVisible(page)
    })
    if (s.orgIds == null && !hiddenPost && !onHiddenWikiPage()) return true
    if (staffSees(COMM_EVENT)) return true
    const partyId = s.userPartyId
    if (partyId && (commEvent.fromPartyId === partyId || commEvent.toPartyId === partyId)) return true
    if (partyId && ec.entity.find('mantle.party.communication.CommunicationEventParty')
            .condition('communicationEventId', commEvent.communicationEventId).condition('partyId', partyId)
            .disableAuthz().count() > 0) return true
    if (mailbox && mailbox.readable.includes(commEvent.contactListId)) return true
    if (depth > 0) return false
    // filed on a record the user may see: the event, or the root of its thread (a record's timeline shows the replies)
    for (const [linkedEntityName, join] of Object.entries(commEventJoins)) {
        for (const row of ec.entity.find(join.entityName).condition('communicationEventId', 'in', eventIds).disableAuthz().list()) {
            if (visible(linkedEntityName, join.keyField, row[join.keyField], depth + 1)) return true
        }
    }
    for (const row of ec.entity.find('mantle.party.communication.CommunicationEventRecord')
            .condition('communicationEventId', 'in', eventIds).disableAuthz().list()) {
        // the chat message an event was made from (findOrCreate#ChatCommunicationEvent) names it, it is no record
        if (row.recordEntityName === 'moqui.chat.ChatEvent') continue
        let keyField = null
        try {
            const keys = Object.keys(ec.entity.makeValue(row.recordEntityName).getPrimaryKeys())
            if (keys.length === 1) keyField = keys[0]
        } catch (err) { keyField = null }
        if (keyField == null) {
            ec.logger.warn(`Communication event ${row.communicationEventId} is filed on ${row.recordEntityName} ${row.recordId}, ` +
                    'which is not a record type, skipped')
            continue
        }
        if (visible(row.recordEntityName, keyField, row.recordId, depth + 1)) return true
    }
    return false
}
// a client contact who signs in (the PROJECT_CLIENT permission; impl-projects.md P10) sees only its client projects'
// shared work efforts, its requests and the messages for it (get#ClientRecordVisibility), no other record type,
// whatever its other groups or entity authorizations, and with authorization disabled too: a framework path that
// runs for the client with authorization off (the webroot chat transitions, a record room's check) must not
// fall through to the internal caller's "everything" (impl-projects.md F121)
let clientUser = null
const isClientUser = () => {
    if (clientUser == null) clientUser = !!ec.user.userId && ec.user.hasPermission('PROJECT_CLIENT')
    return clientUser
}
const clientVisible = (entityName, id) => {
    const parameters = entityName === WORK_EFFORT ? {workEffortIds: [id]} : entityName === REQUEST ? {requestIds: [id]}
            : entityName === COMM_EVENT ? {communicationEventIds: [id]} : null
    if (parameters == null) return false
    const out = ec.service.sync().name('mantle.party.CommunicationServices.get#ClientRecordVisibility').parameters(parameters).call()
    if (ec.message.hasError()) throw new Error(ec.message.getErrorsString())
    return Array.from(out?.visibleWorkEffortIds || []).concat(Array.from(out?.visibleRequestIds || []),
            Array.from(out?.visibleCommunicationEventIds || [])).includes(id)
}
visible = (entityName, keyField, id, depth) => {
    // under the user's entity filters
    const value = ec.entity.find(entityName).condition(keyField, id).one()
    if (value == null) return false
    if (isClientUser()) return clientVisible(entityName, id)
    if (entityName === PARTY) return !value.privateOwnerUserId || value.privateOwnerUserId === ec.user.userId
    if (!authzOn) return true
    if (entityName === COMM_EVENT) return commEventVisible(value, depth)
    if (entityName === WIKI_PAGE) return wikiPageVisible(value)
    // a merge request or a repository: whoever may view the repository (org.moqui.impl.GitServices)
    if (entityName === GIT_MERGE_REQUEST || entityName === GIT_REPOSITORY) return ec.factory.hasFeature('git') && !!ec.service.sync()
            .name('org.moqui.impl.GitServices.get#GitRepositoryAccess').parameter('repositoryId', value.repositoryId).call()?.canView
    // a timesheet: its person, its approvers and ADMIN (mantle.work.TimesheetServices.get#TimesheetAccess)
    if (entityName === TIMESHEET) return !!ec.service.sync()
            .name('mantle.work.TimesheetServices.get#TimesheetAccess').parameter('timesheetId', value.timesheetId).call()?.canView
    if (entityName !== WORK_EFFORT && entityName !== REQUEST && entityName !== ORDER) return true
    const s = userScope()
    if (s.orgIds == null || staffSees(entityName)) return true
    if (entityName === ORDER) return orderVisible(value, s)
    return entityName === WORK_EFFORT ? workEffortVisible(value, s) : requestVisible(value, s)
}

// strict: a check that fails (an exception, or an error from a service it calls) is not visible, and logged
let isVisible = false
ec.message.pushErrors()
try {
    isVisible = visible(recordEntityName, recordKeyField, recordId, 0)
    if (ec.message.hasError()) throw new Error(ec.message.getErrorsString())
} catch (err) {
    ec.logger.error(`Record visibility of ${recordEntityName} ${recordId} for user ${ec.user.userId} not checked, not visible: ` +
            `${err && err.message ? err.message : err}`)
    isVisible = false
} finally {
    ec.message.clearErrors()
    ec.message.popErrors()
}
if (isVisible) recordVisible = true
else refuse(`${recordTypeName} ${recordId} not found`)

created = false
const email = ec.entity.find('moqui.basic.email.EmailMessage').condition('emailMessageId', emailMessageId).disableAuthz().one()
if (email == null) { ec.message.addError(`Email message ${emailMessageId} not found`); return }
const owners = []
if (email.emailAccountId) {
    const access = ec.service.sync().name('org.moqui.impl.EmailClientServices.get#EmailAccountAccess')
            .parameter('emailAccountId', email.emailAccountId).call()
    if (ec.message.hasError()) return
    if (!(access.level >= 1)) { ec.message.addError(`Email message ${emailMessageId} not found`); return }
    if (access.account?.ownerUserId) owners.push(access.account.ownerUserId)
}
if (ec.user.userId) owners.push(ec.user.userId)
const out = ec.service.sync().name('mantle.party.CommunicationServices.create#EmailCommunicationEvent')
        .parameters({emailMessageId: emailMessageId, contactOwnerUserIdList: owners}).disableAuthz().call()
if (ec.message.hasError()) return
communicationEventId = out.communicationEventId ?? null
created = out.created === true

created = false
communicationEventId = null
matchedPartyIdList = []
if (!ec.artifactExecution.authzDisabled()) { ec.message.addError('create#EmailCommunicationEvent is internal'); return }
const cf = ec.entity.conditionFactory
const eventOf = (id) => {
    if (!id) return null
    const found = ec.entity.find('mantle.party.communication.CommunicationEvent').condition('emailMessageId', id)
            .orderBy('communicationEventId').limit(1).list()
    return found.length ? found[0] : null
}
const existing = eventOf(emailMessageId)
if (existing != null) { communicationEventId = existing.communicationEventId; return }
const email = ec.entity.find('moqui.basic.email.EmailMessage').condition('emailMessageId', emailMessageId).one()
if (email == null) { ec.message.addError(`Email message ${emailMessageId} not found`); return }

// the addresses of a header: "Name, Title" <a@b>, c@d
const addressList = (text) => {
    const out = []
    if (!text) return out
    let current = '', quote = false, angle = 0
    const push = () => {
        const entry = current.trim()
        current = ''
        if (!entry) return
        const match = /<([^>]+)>\s*$/.exec(entry)
        const address = (match ? match[1] : entry).trim()
        if (address.includes('@') && !out.some((other) => other.toLowerCase() === address.toLowerCase())) out.push(address)
    }
    for (const ch of String(text)) {
        if (ch === '"') quote = !quote
        else if (ch === '<' && !quote) angle++
        else if (ch === '>' && !quote && angle > 0) angle--
        else if ((ch === ',' || ch === ';') && !quote && angle === 0) { push(); continue }
        current += ch
    }
    push()
    return out.slice(0, 100)
}
