        const kind = commEvent.communicationEventTypeId === 'Comment' ? 'note' : 'message'
        if (!wants(kind)) continue
        entries.push({kind: kind, date: commEvent.entryDate ?? commEvent.datetimeStarted ?? commEvent.lastUpdatedStamp,
            entryKey: `ce:${commEvent.communicationEventId}`, authorPartyId: commEvent.fromPartyId ?? null, authorUserId: null,
            title: commEvent.subject ?? null,
            body: commEvent.body ?? null, contentType: commEvent.contentType ?? null, statusId: commEvent.statusId ?? null,
            source: 'mantle.party.communication.CommunicationEvent', communicationEventId: commEvent.communicationEventId,
            communicationEventTypeId: commEvent.communicationEventTypeId, fromPartyId: commEvent.fromPartyId ?? null,
            toPartyId: commEvent.toPartyId ?? null, parentCommEventId: commEvent.parentCommEventId ?? null,
            rootCommEventId: commEvent.rootCommEventId ?? null, emailMessageId: commEvent.emailMessageId ?? null,
            contactListId: commEvent.contactListId ?? null, editedDate: commEvent.editedDate ?? null})
    }
})

// notes: the record's *Note rows
if (wants('note') && info.noteEntity) runSource('notes', () => {
    let find = ec.entity.find(info.noteEntity.entityName).condition(info.noteEntity.keyField, recordId)
            .orderBy('-noteDate').limit(fetch)
    if (before) find = find.condition(cf.makeCondition('noteDate', 'less', before))
    for (const value of find.list()) {
        const note = value.getMap()
        entries.push({kind: 'note', date: note.noteDate, entryKey: `note:${toMillis(note.noteDate)}`, authorPartyId: null,
            authorUserId: note.userId ?? null,
            title: null, body: note.noteText ?? null, contentType: 'text/plain', statusId: null,
            source: info.noteEntity.entityName, noteDate: note.noteDate, internalNote: note.internalNote ?? null})
    }
})

// activities: the record's calls, emails, to-dos and meetings; done ones in the timeline, open ones planned
if (wants('activity')) runSource('activities', () => {
    const ids = new Set()
    if (info.workEffortJoin) for (const row of ec.entity.find(info.workEffortJoin.entityName)
            .condition(info.workEffortJoin.keyField, recordId).list()) ids.add(row.workEffortId)
    for (const row of ec.entity.find('mantle.work.effort.WorkEffortRecord').condition('recordEntityName', recordEntityName)
            .condition('recordId', recordId).list()) ids.add(row.workEffortId)
    if (ids.size === 0) return
    const nowMillis = toMillis(ec.user.nowTimestamp)
    const activities = ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', 'in', Array.from(ids))
            .condition('purposeEnumId', 'in', ['WepPhoneCall', 'WepEmail', 'WepToDo', 'WepMeeting']).list()
    for (const value of activities) {
        const activity = value.getMap()
        if (activity.statusId === 'WeCancelled') continue
        const assignees = ec.entity.find('mantle.work.effort.WorkEffortParty').condition('workEffortId', activity.workEffortId)
                .condition('roleTypeId', 'Assignee').condition(cf.makeConditionDate('fromDate', 'thruDate', null))
                .orderBy('-fromDate').limit(1).list()
        const assigneePartyId = assignees.length ? assignees[0].partyId : null
        if (activity.statusId === 'WeComplete' || activity.statusId === 'WeClosed') {
            const date = activity.actualCompletionDate ?? activity.estimatedCompletionDate ?? activity.actualStartDate ??
                    activity.estimatedStartDate ?? activity.lastUpdatedStamp
            if (before && toMillis(date) >= before.getTime()) continue
            entries.push({kind: 'activity', date: date, entryKey: `we:${activity.workEffortId}`, authorPartyId: assigneePartyId,
                authorUserId: null,
                title: activity.workEffortName ?? null, body: activity.description ?? null, contentType: null,
                statusId: activity.statusId, source: 'mantle.work.effort.WorkEffort', workEffortId: activity.workEffortId,
                purposeEnumId: activity.purposeEnumId})
        } else {
            const due = activity.purposeEnumId === 'WepMeeting' ? (activity.estimatedStartDate ?? activity.estimatedCompletionDate)
                    : (activity.estimatedCompletionDate ?? activity.estimatedStartDate)
            const dueMillis = toMillis(due)
            plannedActivities.push({workEffortId: activity.workEffortId, workEffortName: activity.workEffortName ?? null,
                description: activity.description ?? null, purposeEnumId: activity.purposeEnumId, statusId: activity.statusId,
                dueDate: dueMillis == null ? null : new Date(dueMillis), overdue: dueMillis != null && dueMillis < nowMillis,
                assigneePartyId: assigneePartyId})
        }
    }
    const dueOf = (activity) => activity.dueDate == null ? Number.MAX_SAFE_INTEGER : activity.dueDate.getTime()
    plannedActivities.sort((left, right) => dueOf(left) - dueOf(right))
})

// changes: the entity audit log of the record's enable-audit-log fields
if (wants('change')) runSource('auditLog', () => {
    let find = ec.entity.find('moqui.entity.EntityAuditLog').condition('changedEntityName', recordEntityName)
            .condition('pkPrimaryValue', recordId).condition(cf.makeCondition('pkSecondaryValue', 'is-null', null))
            .orderBy('-changedDate').limit(fetch).disableAuthz()
    if (before) find = find.condition(cf.makeCondition('changedDate', 'less', before))
    const statusDescription = (statusId) => {
        if (!statusId) return null
        const status = ec.entity.find('moqui.basic.StatusItem').condition('statusId', statusId).useCache(true).one()
        return status ? status.description : statusId
    }
    for (const value of find.list()) {
        const change = value.getMap()
        const isStatus = /statusId$/i.test(change.changedFieldName || '')
        if (clientMode && change.changedFieldName !== 'statusId') continue
        const oldDescription = isStatus ? statusDescription(change.oldValueText) : null
        const newDescription = isStatus ? statusDescription(change.newValueText) : null
        entries.push({kind: 'change', date: change.changedDate, entryKey: `audit:${change.auditHistorySeqId}`, authorPartyId: null,
            authorUserId: change.changedByUserId ?? null,
            title: change.changedFieldName, body: `${oldDescription ?? change.oldValueText ?? ''} → ${newDescription ?? change.newValueText ?? ''}`,
            contentType: 'text/plain', statusId: null, source: 'moqui.entity.EntityAuditLog',
            auditHistorySeqId: change.auditHistorySeqId, fieldName: change.changedFieldName, oldValue: change.oldValueText ?? null,
            newValue: change.newValueText ?? null, oldValueDescription: oldDescription, newValueDescription: newDescription,
            changeReason: change.changeReason ?? null})
    }
})

// files: the record's *Content rows
if (wants('file') && info.contentEntity) runSource('content', () => {
    const contentInfo = info.contentEntity
    let find = ec.entity.find(contentInfo.entityName).condition(contentInfo.keyField, recordId)
            .orderBy('-' + contentInfo.dateField).limit(fetch)
    if (before) find = find.condition(cf.makeCondition(contentInfo.dateField, 'less', before))
    for (const value of find.list()) {
        const row = value.getMap()
        const location = row.contentLocation ? String(row.contentLocation) : ''
        entries.push({kind: 'file', date: row[contentInfo.dateField], entryKey: `file:${Object.values(value.getPrimaryKeys()).join('/')}`,
            authorPartyId: null, authorUserId: row.userId ?? null,
            title: location ? location.substring(location.lastIndexOf('/') + 1) : null, body: row.description ?? null,
            contentType: null, statusId: null, source: contentInfo.entityName, contentKey: value.getPrimaryKeys(),
            contentLocation: row.contentLocation ?? null, contentTypeEnumId: row[contentInfo.typeField] ?? null})
    }
})

// chat: the messages of the room bound to the record, newest first back to the cursor, a page of the room's
// timeline at a time (get#Timeline pages by eventSeq, oldest first in each page)
// a client contact never gets a record room's messages, with authorization disabled too (the framework's chat keeps
// an EXTERNAL_USER out of record rooms as well)
if (wants('chat') && !(ec.user.userId && ec.user.hasPermission('PROJECT_CLIENT'))) runSource('chatRoom', () => {
    let beforeSeq = null
    let found = 0
    for (let pages = 0; pages < 20; pages++) {
        const parameters = {recordEntityName: recordEntityName, recordId: recordId, limit: Math.min(200, Math.max(fetch, 20))}
        if (beforeSeq != null) parameters.beforeSeq = beforeSeq
        const out = callSource('org.moqui.impl.ChatServices.get#Timeline', parameters)
        if (ec.message.hasError() || !out?.room) return
        const room = out.room
        const events = Array.from(out.eventList ?? [])
        for (const event of events) {
            if (event.type !== 'message' || event.redacted) continue
            const sentMillis = toMillis(event.sentDate)
            if (before && sentMillis >= before.getTime()) continue
            entries.push({kind: 'chat', date: sentMillis, entryKey: `chat:${room.chatRoomId}:${event.eventSeq}`,
                authorPartyId: null, authorUserId: event.senderUserId ?? null, authorName: event.senderName ?? null,
                title: room.roomName ?? null, body: event.body ?? null, contentType: 'text/html', bodyText: event.bodyText ?? null,
                statusId: null, source: 'moqui.chat.ChatEvent', chatRoomId: room.chatRoomId, eventSeq: event.eventSeq,
                roomName: room.roomName ?? null, edited: !!event.edited, threadReplyCount: event.threadReplyCount ?? 0,
                chatAttachments: event.attachments ?? [], records: event.records ?? [],
                url: chatRoomUrl ? `${chatRoomUrl}${String(chatRoomUrl).includes('?') ? '&' : '?'}chatRoomId=` +
                    `${encodeURIComponent(room.chatRoomId)}&eventSeq=${event.eventSeq}` : null})
            found++
        }
        if (!out.hasMoreBefore || !events.length || found >= fetch) return
        beforeSeq = events[0].eventSeq
    }
})

// registered sources
const registered = ec.entity.find('moqui.service.ServiceRegister').condition('serviceTypeEnumId', 'RecordTimelineSource')
        .useCache(true).list()
for (const register of (clientMode ? [] : registered)) runSource(register.serviceRegisterId, () => {
    const out = callSource(register.serviceName, {recordEntityName: recordEntityName, recordId: recordId,
        kinds: Array.from(wanted), beforeDate: before, limit: fetch})
    if (ec.message.hasError()) return
    for (const entry of (out?.entryList ?? [])) {
        const kind = kindNames[entry.kind] || entry.kind
        if (!wants(kind)) continue
        if (before && toMillis(entry.date) >= before.getTime()) continue
        const ownKey = entry.entryKey ?? entry.id ?? `${toMillis(entry.date)}:${entry.title ?? ''}`
        entries.push(Object.assign({source: register.serviceName}, entry,
                {kind: kind, entryKey: `${register.serviceRegisterId}:${ownKey}`}))
    }
})

// the union after the cursor, newest first (by entryKey within a date), and the page
const dateOf = (entry) => toMillis(entry.date) ?? 0
const after = beforeMillis == null ? entries : entries.filter((entry) => {
    const millis = dateOf(entry)
    return millis < beforeMillis || (inclusive && millis === beforeMillis && !seen.has(entry.entryKey))
})
after.sort((left, right) => dateOf(right) - dateOf(left)
        || (left.entryKey < right.entryKey ? 1 : left.entryKey > right.entryKey ? -1 : 0))
hasMore = after.length > start + pageSize
const page = after.slice(start, start + pageSize)
// the next page's cursor: the last entry's date and the keys shown so far of that date
if (page.length) {
    const lastMillis = dateOf(page[page.length - 1])
    nextBeforeDate = new Date(lastMillis)
    nextSeenKeys = after.slice(0, start + pageSize).filter((entry) => dateOf(entry) === lastMillis)
            .map((entry) => entry.entryKey)
    if (inclusive && lastMillis === beforeMillis) for (const key of seen) if (!nextSeenKeys.includes(key)) nextSeenKeys.push(key)
}
for (const entry of page) entry.date = entry.date == null ? null : new Date(dateOf(entry))

// the attachments of the messages and notes shown
const commEventIds = page.filter((entry) => entry.communicationEventId).map((entry) => entry.communicationEventId)
if (commEventIds.length) runSource('attachments', () => {
    const byEvent = {}
    for (const value of ec.entity.find('mantle.party.communication.CommunicationEventContent')
            .condition('communicationEventId', 'in', commEventIds).orderBy('sequenceNum,contentDate').list()) {
        const row = value.getMap()
        const location = row.contentLocation ? String(row.contentLocation) : ''
        ;(byEvent[row.communicationEventId] ??= []).push({communicationEventContentId: row.communicationEventContentId,
            contentLocation: row.contentLocation ?? null, fileName: location ? location.substring(location.lastIndexOf('/') + 1) : null,
            contentTypeEnumId: row.contentTypeEnumId ?? null, description: row.description ?? null})
    }
    for (const entry of page) if (entry.communicationEventId) entry.attachments = byEvent[entry.communicationEventId] ?? []
})
// the author's party of the entries that have only a user
const userIds = Array.from(new Set(page.filter((entry) => entry.authorUserId && !entry.authorPartyId).map((entry) => entry.authorUserId)))
if (userIds.length) runSource('authors', () => {
    const partyByUser = {}
    for (const account of ec.entity.find('moqui.security.UserAccount').condition('userId', 'in', userIds).disableAuthz().list())
        partyByUser[account.userId] = account.partyId
    for (const entry of page) if (entry.authorUserId && !entry.authorPartyId) entry.authorPartyId = partyByUser[entry.authorUserId] ?? null
})
entryList = page

mentionedUserIds = []
notifiedFollowerUserIds = []
let rootCommEventId = null
if (parentCommEventId) {
    const parent = ec.entity.find('mantle.party.communication.CommunicationEvent').condition('communicationEventId', parentCommEventId).one()
    if (parent == null) { ec.message.addError(`Communication event ${parentCommEventId} not found`); return }
    rootCommEventId = parent.rootCommEventId || parentCommEventId
}
const messageOut = ec.service.sync().name('mantle.party.CommunicationServices.create#Message').parameters({
    communicationEventTypeId: 'Comment', contactMechTypeEnumId: 'CmtWebForm', statusId: 'CeSent', subject: subject,
    body: body, contentType: contentType, parentCommEventId: parentCommEventId, rootCommEventId: rootCommEventId}).call()
if (ec.message.hasError()) return
communicationEventId = messageOut.communicationEventId
const linkOut = ec.service.sync().name('mantle.party.CommunicationServices.link#CommunicationEventRecord')
        .parameters({communicationEventId: communicationEventId, recordEntityName: recordEntityName, recordId: recordId}).call()
if (ec.message.hasError()) return
linkEntityName = linkOut.linkEntityName

const notifyParameters = {recordEntityName: linkOut.recordEntityName, recordId: recordId, communicationEventId: communicationEventId,
    subject: subject, body: body, recordUrl: recordUrl}
if (mentionUserIds?.length || mentionPartyIds?.length) {
    const mentionOut = ec.service.sync().name('mantle.party.CommunicationServices.notify#RecordMention')
            .parameters(Object.assign({mentionUserIds: mentionUserIds, mentionPartyIds: mentionPartyIds}, notifyParameters)).call()
    if (ec.message.hasError()) return
    mentionedUserIds = mentionOut.notifiedUserIds
}
const followerOut = ec.service.sync().name('mantle.party.CommunicationServices.notify#RecordFollowers')
        .parameters(Object.assign({kind: 'notes', excludeUserIds: mentionedUserIds}, notifyParameters)).call()
if (ec.message.hasError()) return
notifiedFollowerUserIds = followerOut.notifiedUserIds

isAuthor = false
isAdmin = false
ownJoin = null
if (action !== 'update' && action !== 'delete') { ec.message.addError(`Note action ${action} is not update or delete`); return }
const info = ec.service.sync().name('mantle.party.CommunicationServices.get#RecordLinkInfo')
        .parameters({recordEntityName: recordEntityName, recordId: recordId}).call()
if (ec.message.hasError()) return
recordEntityName = info.recordEntityName
const notFound = () => ec.message.addError(`Note ${communicationEventId} not found on ${info.recordTypeName} ${recordId}`)
const value = ec.entity.find('mantle.party.communication.CommunicationEvent').condition('communicationEventId', communicationEventId).one()
if (value == null || value.statusId === 'CeCancelled') { notFound(); return }
const found = (entityName, keys) => ec.entity.find(entityName).condition(keys).count() > 0
let on = false
if (info.isParty) {
    on = value.fromPartyId === recordId || value.toPartyId === recordId ||
            found('mantle.party.communication.CommunicationEventParty', {communicationEventId: communicationEventId, partyId: recordId})
} else {
    for (const id of [value.communicationEventId, value.rootCommEventId].filter((item) => item)) {
        if (info.commEventJoin && found(info.commEventJoin.entityName, {communicationEventId: id, [info.commEventJoin.keyField]: recordId})) {
            on = true
            if (id === value.communicationEventId) ownJoin = info.commEventJoin
        } else if (found('mantle.party.communication.CommunicationEventRecord', {communicationEventId: id,
                recordEntityName: recordEntityName, recordId: recordId})) {
            on = true
        }
        if (on) break
    }
}
if (!on) { notFound(); return }
if (value.communicationEventTypeId !== 'Comment') {
    ec.message.addError(action === 'update' ? 'Only a note or a comment can be changed: a message once sent stays as it is'
            : 'Only a note or a comment can be deleted: take a message off the record instead')
    return
}
const partyId = ec.user.userAccount?.partyId || null
isAuthor = !!partyId && value.fromPartyId === partyId
isAdmin = !!ec.user.userId && ec.user.isInGroup('ADMIN')
if (action === 'update' && !isAuthor) { ec.message.addError('You may change only your own notes'); return }
if (action === 'delete') {
    if (!isAuthor && !isAdmin) { ec.message.addError('You may delete only your own notes'); return }
    const cf = ec.entity.conditionFactory
    const replies = ec.entity.find('mantle.party.communication.CommunicationEvent').condition(cf.makeCondition([
        cf.makeCondition('parentCommEventId', 'equals', communicationEventId),
        cf.makeCondition('rootCommEventId', 'equals', communicationEventId)], 'or'))
            .condition(cf.makeCondition('communicationEventId', 'not-equals', communicationEventId)).count()
    if (replies > 0) { ec.message.addError('This note has replies: delete the replies first'); return }
}
commEvent = value.getMap()

mentionedUserIds = []
editedDate = null
const access = ec.service.sync().name('mantle.party.CommunicationServices.check#RecordNoteAccess').parameters({
    recordEntityName: recordEntityName, recordId: recordId, communicationEventId: communicationEventId, action: 'update'}).call()
if (ec.message.hasError()) return
const old = access.commEvent
const text = String(body || '').replace(/<[^>]*>/g, ' ').replace(/&nbsp;/g, ' ').trim()
if (!text) { ec.message.addError('A note needs its text: delete it instead'); return }
const newSubject = subject != null && String(subject).trim() !== '' ? subject : (old.subject ?? null)
const newType = contentType || old.contentType || 'text/plain'
if (access.ownJoin && access.recordEntityName === 'mantle.request.Request') {
    ec.service.sync().name('mantle.request.RequestServices.update#RequestComment').parameters({requestId: recordId,
        communicationEventId: communicationEventId, subject: newSubject, body: body, contentType: newType}).call()
} else {
    ec.service.sync().name('update#mantle.party.communication.CommunicationEvent').parameters({communicationEventId: communicationEventId,
        subject: newSubject, body: body, contentType: newType, editedDate: ec.user.nowTimestamp}).call()
}
if (ec.message.hasError()) return
editedDate = ec.entity.find('mantle.party.communication.CommunicationEvent').condition('communicationEventId', communicationEventId)
        .one()?.editedDate ?? ec.user.nowTimestamp

// the users mentioned now and not before: a data-mention-id of the old body is a userId or a partyId
const cf = ec.entity.conditionFactory
const usersOf = (ids) => {
    const list = Array.from(new Set(Array.from(ids || []).map((id) => String(id).trim()).filter((id) => id)))
    if (!list.length) return new Set()
    return new Set(Array.from(ec.entity.find('moqui.security.UserAccount').condition(cf.makeCondition([
        cf.makeCondition('userId', 'in', list), cf.makeCondition('partyId', 'in', list)], 'or'))
            .selectField('userId').disableAuthz().list()).map((account) => account.userId))
}
const before = usersOf(Array.from(String(old.body || '').matchAll(/data-mention-id="([^"]+)"/g)).map((match) => match[1]))
const now = new Set(Array.from(mentionUserIds || []).map((id) => String(id).trim()).filter((id) => id))
if (mentionPartyIds?.length) for (const account of ec.entity.find('moqui.security.UserAccount')
        .condition('partyId', 'in', Array.from(mentionPartyIds)).selectField('userId').disableAuthz().list()) now.add(account.userId)
const added = Array.from(now).filter((id) => !before.has(id) && id !== ec.user.userId)
if (added.length === 0) return
const mentionOut = ec.service.sync().name('mantle.party.CommunicationServices.notify#RecordMention').parameters({
    recordEntityName: access.recordEntityName, recordId: recordId, communicationEventId: communicationEventId,
    mentionUserIds: added, subject: newSubject, body: body, recordUrl: recordUrl}).call()
if (ec.message.hasError()) return
mentionedUserIds = Array.from(mentionOut?.notifiedUserIds || [])

deleted = false
const access = ec.service.sync().name('mantle.party.CommunicationServices.check#RecordNoteAccess').parameters({
    recordEntityName: recordEntityName, recordId: recordId, communicationEventId: communicationEventId, action: 'delete'}).call()
if (ec.message.hasError()) return
if (access.ownJoin && access.recordEntityName === 'mantle.request.Request') {
    ec.service.sync().name('mantle.request.RequestServices.delete#RequestComment').parameters({requestId: recordId,
        communicationEventId: communicationEventId}).call()
} else {
    ec.service.sync().name('mantle.party.CommunicationServices.delete#CommunicationEventRows')
            .parameter('communicationEventId', communicationEventId).call()
}
if (ec.message.hasError()) return
deleted = true

deletedFileCount = 0
const COMM_EVENT = 'mantle.party.communication.CommunicationEvent'
const value = ec.entity.find(COMM_EVENT).condition('communicationEventId', communicationEventId).one()
if (value == null) { ec.message.addError(`Communication event ${communicationEventId} not found`); return }
const cf = ec.entity.conditionFactory
const replies = ec.entity.find(COMM_EVENT).condition(cf.makeCondition([
    cf.makeCondition('parentCommEventId', 'equals', communicationEventId),
    cf.makeCondition('rootCommEventId', 'equals', communicationEventId)], 'or'))
        .condition(cf.makeCondition('communicationEventId', 'not-equals', communicationEventId)).count()
if (replies > 0) { ec.message.addError('This note has replies: delete the replies first'); return }
for (const entityName of ['mantle.party.communication.CommunicationEventRecord', 'mantle.request.RequestCommEvent',
        'mantle.work.effort.WorkEffortCommEvent', 'mantle.order.OrderCommunicationEvent',
        'mantle.party.communication.WikiPageCommunicationEvent', 'mantle.party.communication.CommunicationEventParty',
        'mantle.party.communication.CommunicationEventPurpose', 'mantle.party.communication.CommunicationEventProduct']) {
    ec.entity.find(entityName).condition('communicationEventId', communicationEventId).deleteAll()
}
// the attachments: a file of the event's own content folder goes with its row (save#CommunicationEventContentFile)
const folder = `/CommunicationEvent/${communicationEventId}/`
for (const content of ec.entity.find('mantle.party.communication.CommunicationEventContent')
        .condition('communicationEventId', communicationEventId).list()) {
    const location = content.contentLocation ? String(content.contentLocation) : null
    content.delete()
    if (!location || !location.includes(folder)) continue
    try {
        const ref = ec.resource.getLocationReference(location)
        if (ref && ref.getExists()) { ref.delete(); deletedFileCount++ }
    } catch (err) {
        ec.logger.warn(`Communication event ${communicationEventId}: the row of ${location} is deleted, the file was not: ${err}`)
    }
}
ec.service.sync().name('delete#' + COMM_EVENT).parameter('communicationEventId', communicationEventId).call()

const ids = Array.from(new Set(Array.from(userIds || []).filter((id) => id)))
userIds = ids
if (!ids.length) return
const wasDisabled = ec.artifactExecution.disableAuthz()
try {
    const cf = ec.entity.conditionFactory
    const clients = new Set(Array.from(ec.entity.find('moqui.security.UserPermissionCheck').condition('userId', 'in', ids)
            .condition('userPermissionId', 'PROJECT_CLIENT').condition(cf.makeConditionDate('groupFromDate', 'groupThruDate', null))
            .condition(cf.makeConditionDate('permissionFromDate', 'permissionThruDate', null)).list()).map((row) => row.userId))
    if (!clients.size) return
    userIds = ids.filter((id) => {
        if (!clients.has(id)) return true
        if (!communicationEventId) return false
        ec.message.pushErrors()
        try {
            const out = ec.service.sync().name('mantle.party.CommunicationServices.get#ClientRecordVisibility')
                    .parameters({userId: id, communicationEventIds: [communicationEventId]}).call()
            if (ec.message.hasError()) throw new Error(ec.message.getErrorsString())
            return Array.from(out?.visibleCommunicationEventIds || []).includes(communicationEventId)
        } catch (err) {
            ec.logger.error(`Client user ${id} left out of the notice of communication event ${communicationEventId}: ${err}`)
            return false
        } finally {
            ec.message.clearErrors()
            ec.message.popErrors()
        }
    })
} finally {
    if (!wasDisabled) ec.artifactExecution.enableAuthz()
}

notifiedUserIds = []
const userIds = new Set(mentionUserIds ? Array.from(mentionUserIds) : [])
if (mentionPartyIds?.length) for (const account of ec.entity.find('moqui.security.UserAccount')
        .condition('partyId', 'in', Array.from(mentionPartyIds)).disableAuthz().list()) userIds.add(account.userId)
userIds.delete(authorUserId)
if (userIds.size === 0) return
// a client contact is told only of a message for it (impl-projects.md P10)
const audience = ec.service.sync().name('mantle.party.CommunicationServices.filter#ClientAudience')
        .parameters({userIds: Array.from(userIds), communicationEventId: communicationEventId || null}).call()?.userIds || []
userIds.clear()
for (const id of audience) userIds.add(id)
if (userIds.size === 0) return
const message = ec.service.sync().name('mantle.party.CommunicationServices.make#RecordNotificationMessage').parameters({
    recordEntityName: recordEntityName, recordId: recordId, communicationEventId: communicationEventId, subject: subject,
    body: body, authorUserId: authorUserId}).call().message
try {
    const nm = ec.makeNotificationMessage().topic('ChatterMention').message(message).userIds(Array.from(userIds))
    if (recordUrl) nm.link(recordUrl)
    nm.send()
    notificationMessageId = nm.getNotificationMessageId()
    notifiedUserIds = Array.from(nm.getNotifyUserIds() ?? [])
} catch (err) {
    ec.logger.error(`Mention notification for ${recordEntityName} ${recordId} not sent: ${err}`)
}

notifiedUserIds = []
const flagFields = {messages: 'notifyMessages', notes: 'notifyNotes', activities: 'notifyActivities', changes: 'notifyChanges'}
const flagField = flagFields[kind]
if (!flagField) { ec.message.addError(`Follower kind ${kind} is not one of messages, notes, activities, changes`); return }
const excluded = new Set(excludeUserIds ? Array.from(excludeUserIds) : [])
excluded.add(authorUserId)
const followers = ec.entity.find('mantle.party.communication.RecordFollower').condition('recordEntityName', recordEntityName)
        .condition('recordId', recordId).condition(flagField, 'Y').list()
        .map((follower) => follower.userId).filter((userId) => !excluded.has(userId))
// a client contact is told only of a message for it, never of a note, activity or change (impl-projects.md P10)
const userIds = followers.length ? Array.from(ec.service.sync().name('mantle.party.CommunicationServices.filter#ClientAudience')
        .parameters({userIds: followers, communicationEventId: kind === 'messages' ? (communicationEventId || null) : null})
        .call()?.userIds || []) : []
if (userIds.length === 0) return
const message = ec.service.sync().name('mantle.party.CommunicationServices.make#RecordNotificationMessage').parameters({
    recordEntityName: recordEntityName, recordId: recordId, communicationEventId: communicationEventId, subject: subject,
    body: body, authorUserId: authorUserId}).call().message
message.kind = kind
message.workEffortId = workEffortId ?? null
try {
    const nm = ec.makeNotificationMessage().topic('RecordFollow').message(message).userIds(userIds)
    if (recordUrl) nm.link(recordUrl)
    nm.send()
    notificationMessageId = nm.getNotificationMessageId()
    notifiedUserIds = Array.from(nm.getNotifyUserIds() ?? [])
} catch (err) {
    ec.logger.error(`Follower notification for ${recordEntityName} ${recordId} not sent: ${err}`)
}

let recordTypeName = recordEntityName.substring(recordEntityName.lastIndexOf('.') + 1)
try { recordTypeName = ec.entity.makeValue(recordEntityName).getEntityNamePretty() } catch (err) { /* the short name */ }
const author = authorUserId ? ec.entity.find('moqui.security.UserAccount').condition('userId', authorUserId).disableAuthz().one() : null
const text = body ? String(body).replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim() : ''
message = {recordEntityName: recordEntityName, recordId: recordId, recordName: `${recordTypeName} ${recordId}`,
    communicationEventId: communicationEventId ?? null, authorUserId: authorUserId ?? null,
    authorName: author ? (author.userFullName || author.username) : 'Someone', subject: subject ?? null,
    summary: subject || (text.length > 120 ? text.substring(0, 117) + '...' : text)}

if (!userId) { ec.message.addError('A user is required to follow a record'); return }
const info = ec.service.sync().name('mantle.party.CommunicationServices.get#RecordLinkInfo')
        .parameters({recordEntityName: recordEntityName, recordId: recordId}).call()
if (ec.message.hasError()) return
const flagFields = {messages: 'notifyMessages', notes: 'notifyNotes', activities: 'notifyActivities', changes: 'notifyChanges'}
const keys = {recordEntityName: info.recordEntityName, recordId: recordId, userId: userId}
const existing = ec.entity.find('mantle.party.communication.RecordFollower').condition(keys).one()
let flags = null
const kindList = (kinds == null ? [] : (typeof kinds === 'string' ? kinds.split(',') : Array.from(kinds)))
        .map((kind) => String(kind).trim()).filter((kind) => kind)
if (kindList.length) {
    const unknown = kindList.filter((kind) => !flagFields[kind])
    if (unknown.length) { ec.message.addError(`Follower kinds ${unknown.join(', ')} are not messages, notes, activities or changes`); return }
    flags = {}
    for (const [kind, field] of Object.entries(flagFields)) flags[field] = kindList.includes(kind) ? 'Y' : 'N'
}
if (existing != null) {
    fromDate = existing.fromDate
    if (flags) ec.service.sync().name('update#mantle.party.communication.RecordFollower').parameters(Object.assign({}, keys, flags)).call()
} else {
    fromDate = ec.user.nowTimestamp
    ec.service.sync().name('create#mantle.party.communication.RecordFollower').parameters(Object.assign({fromDate: fromDate},
            flags || {notifyMessages: 'Y', notifyNotes: 'Y', notifyActivities: 'Y', notifyChanges: 'N'}, keys)).call()
}

let entityName = recordEntityName
try { entityName = ec.entity.makeValue(recordEntityName).getEntityName() } catch (err) { /* as given */ }
const keys = {recordEntityName: entityName, recordId: recordId, userId: userId}
if (ec.entity.find('mantle.party.communication.RecordFollower').condition(keys).one() != null)
    ec.service.sync().name('delete#mantle.party.communication.RecordFollower').parameters(keys).call()

followerList = []
isFollowing = false
const info = ec.service.sync().name('mantle.party.CommunicationServices.get#RecordLinkInfo')
        .parameters({recordEntityName: recordEntityName, recordId: recordId}).call()
if (ec.message.hasError()) return
for (const follower of ec.entity.find('mantle.party.communication.RecordFollower').condition('recordEntityName', info.recordEntityName)
        .condition('recordId', recordId).orderBy('fromDate').list()) {
    const account = ec.entity.find('moqui.security.UserAccount').condition('userId', follower.userId).disableAuthz().one()
    followerList.push({userId: follower.userId, username: account?.username ?? null, userFullName: account?.userFullName ?? null,
        partyId: account?.partyId ?? null, notifyMessages: follower.notifyMessages, notifyNotes: follower.notifyNotes,
        notifyActivities: follower.notifyActivities, notifyChanges: follower.notifyChanges, fromDate: follower.fromDate})
    if (follower.userId === ec.user.userId) isFollowing = true
}

communicationEventId = null
created = false
chatMessage = null
const parse = (text) => { if (!text) return {}; try { const value = JSON.parse(text); return value && typeof value === 'object' ? value : {} } catch (err) { return {} } }
const access = ec.service.sync().name('org.moqui.impl.ChatServices.get#RoomAccess').parameter('chatRoomId', chatRoomId).call()
if (ec.message.hasError()) return
if (!access?.canRead) { ec.message.addError(`Chat room ${chatRoomId} not found`); return }
const row = ec.entity.find('moqui.chat.ChatEvent').condition('chatRoomId', chatRoomId).condition('eventSeq', eventSeq).one()
if (row == null || row.eventTypeEnumId !== 'CetMessage' || row.redactedDate) {
    ec.message.addError(`Message ${eventSeq} not found in the room`); return }
const content = parse(row.contentJson)
let html = content.body ?? null
if (row.lastEditEventSeq != null) {
    const edit = ec.entity.find('moqui.chat.ChatEvent').condition('chatRoomId', chatRoomId).condition('eventSeq', row.lastEditEventSeq).one()
    const edited = parse(edit?.contentJson)
    if (edited.body != null) html = edited.body
}
const room = access.room
const sender = row.senderUserId ? ec.entity.find('moqui.security.UserAccount').condition('userId', row.senderUserId)
        .disableAuthz().one() : null
chatMessage = {chatRoomId: chatRoomId, eventSeq: Number(eventSeq), senderUserId: row.senderUserId ?? null,
    senderName: sender ? (sender.userFullName || sender.username) : null, senderPartyId: sender?.partyId ?? null,
    sentDate: row.sentDate, body: html, bodyText: row.bodyText ?? null,
    attachmentNames: Array.from(content.attachments ?? []).map((file) => file.fileName).filter((name) => name),
    roomName: room.roomName ?? null, roomRecordEntityName: room.recordEntityName ?? null, roomRecordId: room.recordId ?? null}

const messageKey = `${chatRoomId}::${eventSeq}`
const existing = Array.from(ec.entity.find('mantle.party.communication.CommunicationEventRecord')
        .condition('recordEntityName', 'moqui.chat.ChatEvent').condition('recordId', messageKey).list())
if (existing.length) { communicationEventId = existing[0].communicationEventId; return }
communicationEventId = ec.service.sync().name('create#mantle.party.communication.CommunicationEvent').parameters({
    communicationEventTypeId: 'Chat', statusId: 'CeSent', fromPartyId: chatMessage.senderPartyId, entryDate: row.sentDate,
    datetimeStarted: row.sentDate, subject: room.roomName ?? null, contentType: 'text/html', body: html}).call()?.communicationEventId
if (ec.message.hasError()) return
ec.service.sync().name('create#mantle.party.communication.CommunicationEventRecord').parameters({communicationEventId: communicationEventId,
    recordEntityName: 'moqui.chat.ChatEvent', recordId: messageKey, linkedByUserId: ec.user.userId, linkedDate: ec.user.nowTimestamp}).call()
created = !ec.message.hasError()

recordEntityName = null; recordId = null; workEffortId = null; requestId = null
roomRecordEntityName = null; roomRecordId = null; roomRecordLinked = false
const kind = String(recordKind || '').trim().toLowerCase()
if (!['task', 'request', 'event'].includes(kind)) { ec.message.addError(`A record from a chat message is a task, request or event, not ${recordKind}`); return }
const myPartyId = ec.user.userAccount?.partyId || null
if (!myPartyId) { ec.message.addError('Making a record from a chat message needs a user with a party'); return }
const found = ec.service.sync().name('mantle.party.CommunicationServices.findOrCreate#ChatCommunicationEvent')
        .parameters({chatRoomId: chatRoomId, eventSeq: eventSeq}).call()
if (ec.message.hasError()) return
communicationEventId = found.communicationEventId
const chatMessage = found.chatMessage
const text = String(chatMessage.bodyText ?? '').trim()

let title = name != null ? String(name).trim() : ''
if (!title) {
    const firstLine = (text.split(/\r?\n/).map((line) => line.replace(/\s+/g, ' ').trim()).find((line) => line) || '')
    title = firstLine.length > 100 ? firstLine.substring(0, 99) + '…' : firstLine
}
if (!title) title = chatMessage.attachmentNames.length ? chatMessage.attachmentNames.join(', ').substring(0, 100)
        : ec.resource.expand('Message from ${name}', '', {name: chatMessage.senderName || chatMessage.senderUserId || ''})
const details = description != null ? (String(description) || null) : (text || null)

if (kind === 'task') {
    workEffortId = ec.service.sync().name('mantle.work.TaskServices.create#SimpleTask').parameters({workEffortName: title,
        description: details, purposeEnumId: purposeEnumId || 'WepTask', priority: priority ?? 5,
        estimatedCompletionDate: estimatedCompletionDate, assignToPartyId: assignToPartyId || myPartyId,
        ownerPartyId: myPartyId}).call()?.workEffortId
    recordEntityName = 'mantle.work.effort.WorkEffort'; recordId = workEffortId
} else if (kind === 'event') {
    const fields = {workEffortName: title, description: details, purposeEnumId: purposeEnumId || 'WepMeeting', priority: priority ?? 5,
        assignToPartyId: assignToPartyId || myPartyId, ownerPartyId: myPartyId}
    if (allDayStart) Object.assign(fields, {allDayStart: allDayStart, allDayEnd: allDayEnd || null})
    else {
        const toMillis = (value) => {
            if (value == null || value === '') return null
            if (typeof value === 'number') return value
            if (value instanceof Date) return value.getTime()
            const text = String(value)
            if (/^-?\d+$/.test(text)) return Number(text)
            const parsed = Date.parse(text)
            return Number.isNaN(parsed) ? null : parsed
        }
        // with no start, the next whole hour
        const startMs = toMillis(estimatedStartDate) ?? Math.floor(toMillis(ec.user.nowTimestamp) / 3600000) * 3600000 + 3600000
        let endMs = toMillis(estimatedCompletionDate)
        if (endMs == null || endMs <= startMs) endMs = startMs + 3600000
        Object.assign(fields, {estimatedStartDate: new Date(startMs), estimatedCompletionDate: new Date(endMs),
            estimatedWorkDuration: (endMs - startMs) / 3600000, timeUomId: 'TF_hr'})
    }
    let eventCalendarId = calendarId || null
    if (!eventCalendarId) {
        eventCalendarId = ec.service.sync().name('mantle.work.CalendarServices.ensure#UserDefaultCalendar').call()?.calendarId || null
        if (ec.message.hasError()) return
    }
    fields.calendarId = eventCalendarId
    workEffortId = ec.service.sync().name('mantle.work.EventServices.create#Event').parameters(fields).call()?.workEffortId
    recordEntityName = 'mantle.work.effort.WorkEffort'; recordId = workEffortId
} else {
    requestId = ec.service.sync().name('mantle.request.RequestServices.create#Request').parameters({requestName: title,
        description: details, statusId: 'ReqSubmitted', requestTypeEnumId: requestTypeEnumId || 'RqtSupport', priority: priority ?? 5,
        assignToPartyId: assignToPartyId || null}).call()?.requestId
    recordEntityName = 'mantle.request.Request'; recordId = requestId
}
if (ec.message.hasError()) return
if (!recordId) { ec.message.addError(`The ${kind} was not made`); return }

// the message on the new record
ec.service.sync().name('mantle.party.CommunicationServices.link#CommunicationEventRecord').parameters({
    communicationEventId: communicationEventId, recordEntityName: recordEntityName, recordId: recordId}).call()
if (ec.message.hasError()) return

// the room's record: linked as well, failure tolerant
roomRecordEntityName = chatMessage.roomRecordEntityName
roomRecordId = chatMessage.roomRecordId
if (!linkRoomRecord || !roomRecordEntityName || !roomRecordId) return
ec.message.pushErrors()
try {
    if (workEffortId) {
        ec.service.sync().name('mantle.work.WorkEffortServices.link#WorkEffortRecord').parameters({workEffortId: workEffortId,
            recordEntityName: roomRecordEntityName, recordId: roomRecordId}).call()
        if (ec.message.hasError()) throw new Error(ec.message.getErrorsString())
        roomRecordLinked = true
    } else if (roomRecordEntityName === 'mantle.work.effort.WorkEffort') {
        ec.service.sync().name('mantle.party.CommunicationServices.get#RecordLinkInfo').parameters({
            recordEntityName: roomRecordEntityName, recordId: roomRecordId}).call()
        if (ec.message.hasError()) throw new Error(ec.message.getErrorsString())
        const keys = {requestId: requestId, workEffortId: roomRecordId}
        if (ec.entity.find('mantle.request.RequestWorkEffort').condition(keys).one() == null)
            ec.service.sync().name('create#mantle.request.RequestWorkEffort').parameters(keys).call()
        if (ec.message.hasError()) throw new Error(ec.message.getErrorsString())
        roomRecordLinked = true
    }
} catch (err) {
    ec.logger.warn(`The ${kind} ${recordId} from chat message ${chatRoomId}::${eventSeq} is not linked to the room's record ` +
            `${roomRecordEntityName} ${roomRecordId}: ${err && err.message ? err.message : err}`)
    roomRecordLinked = false
} finally {
    ec.message.clearErrors()
    ec.message.popErrors()
}
